70	/* ── Chunked transfer decoding ───────────────────────────────── */
71	
72	/**
73	 * Decode chunked transfer encoding in-place.
74	 * Format: <hex-size>\r\n<data>\r\n ... 0\r\n\r\n
75	 * Returns the decoded length.
76	 */
77	static size_t decode_chunked(char* buf, size_t len)
78	{
79	    char* src = buf;
80	    char* end = buf + len;
81	    char* dst = buf;
82	
83	    while (src < end) {
84	        /* Find end of chunk-size line */
85	        char* crlf = (char*)memmem(src, (size_t)(end - src), "\r\n", 2);
86	        if (!crlf)
87	            break;
88	
89	        /* Parse hex chunk size */
90	        char* endptr;
91	        long chunk_sz = strtol(src, &endptr, 16);
92	
93	        /* Validate: endptr should reach the CRLF (skip spaces) */
94	        while (endptr < crlf && *endptr == ' ')
95	            endptr++;
96	
97	        if (endptr != crlf || chunk_sz < 0 || chunk_sz > (long)(end - crlf - 2))
98	            break;  /* malformed or oversized chunk header */
99	
100	        if (chunk_sz == 0)
101	            break;  /* final chunk */
102	
103	        src = crlf + 2;  /* skip past chunk-size CRLF */
104	
105	        /* Clamp to available data */
106	        if (src + chunk_sz > end)
107	            chunk_sz = (long)(end - src);
108	
109	        memmove(dst, src, (size_t)chunk_sz);
110	        dst += chunk_sz;
111	        src += chunk_sz;
112	
113	        /* Skip trailing CRLF after chunk data */
114	        if (src + 2 <= end && src[0] == '\r' && src[1] == '\n')
115	            src += 2;
116	    }
117	
118	    return (size_t)(dst - buf);
119	}
