123	typedef struct {
124	    mbedtls_ssl_context ssl;
125	    mbedtls_ssl_config cfg;
126	    mbedtls_net_context net;
127	    mbedtls_ctr_drbg_context ctr_drbg;
128	    bool abort_on_close;
129	    unsigned send_pressure;
130	} tls_ctx_t;
