132	/* NuttX may report temporary packet-buffer pressure as ENOMEM, including
133	 * during handshake. Translate it at the BIO boundary so mbedTLS retains
134	 * the pending TLS record and the controlled poll loop applies its budget. */
135	static int tls_controlled_send(void *arg, const unsigned char *buf, size_t len)
136	{
137	    tls_ctx_t *ctx = arg;
138	    int ret = mbedtls_net_send(&ctx->net, buf, len);
139	    int error = errno;
140	    if (ret == MBEDTLS_ERR_NET_SEND_FAILED && error == ENOMEM) {
141	        if (ctx->send_pressure++ == 0)
142	            syslog(LOG_INFO, "[%s] controlled send waiting for packet buffers\n", TAG);
143	        return MBEDTLS_ERR_SSL_WANT_WRITE;
144	    }
145	    return ret;
146	}
147	
148	static int tls_controlled_recv(void *arg, unsigned char *buf, size_t len)
149	{
150	    tls_ctx_t *ctx = arg;
151	    return mbedtls_net_recv(&ctx->net, buf, len);
152	}
