319	static int tls_dns_budget(void *arg)
320	{
321	    const vela_req_ctl_t *ctl = arg;
322	    if (vela_req_cancelled(ctl)) return -ECANCELED;
323	    int32_t remaining = vela_req_budget_ms(ctl, agent_mono_ms());
324	    return remaining < 0 ? INT32_MAX : remaining;
