327	static int tls_resolve_controlled(const char *host, const char *port,
328	    const struct addrinfo *hints, struct addrinfo **addresses,
329	    const vela_req_ctl_t *ctl)
330	{
331	    struct addrinfo numeric = *hints;
332	    struct sockaddr_storage resolved[4];
333	    struct dns_query_control_s control = {0};
334	    struct addrinfo **tail = addresses;
335	    int n = 4;
336	    int ret;
337	
338	    numeric.ai_flags |= AI_NUMERICHOST | AI_NUMERICSERV;
339	    ret = getaddrinfo(host, port, &numeric, addresses);
340	    if (ret == 0) return 0;
341	
342	#if defined(CONFIG_VG_HMI)
343	    bool is_target = (host != NULL && strcmp(host, "token-plan-cn.xiaomimimo.com") == 0);
344	    uint32_t now = agent_mono_ms();
345	    if (is_target) {
346	        pthread_mutex_lock(&voice_dns_lock);
347	        if (voice_dns_count > 0 && (uint32_t)(now - voice_dns_saved) < 300000) {
348	            n = voice_dns_count;
349	            memcpy(resolved, voice_dns_addrs, sizeof(struct sockaddr_storage) * (size_t)n);
350	            pthread_mutex_unlock(&voice_dns_lock);
351	            goto convert;
352	        }
353	        pthread_mutex_unlock(&voice_dns_lock);
354	    }
355	#endif
