357	    control.budget_ms = tls_dns_budget;
358	    control.arg = (void *)ctl;
359	    ret = dns_query_controlled(host, resolved, &n, &control);
360	    if (ret < 0) return ret;
361	
362	#if defined(CONFIG_VG_HMI)
363	    if (is_target && n > 0) {
