365	        voice_dns_count = n > 4 ? 4 : n;
366	        memcpy(voice_dns_addrs, resolved, sizeof(struct sockaddr_storage) * (size_t)voice_dns_count);
367	        voice_dns_saved = now;
368	        pthread_mutex_unlock(&voice_dns_lock);
369	    }
370	convert:
