375	        struct addrinfo *entry = NULL;
376	        if (resolved[i].ss_family == AF_INET) {
377	            address = &((struct sockaddr_in *)&resolved[i])->sin_addr;
378	        } else if (resolved[i].ss_family == AF_INET6) {
379	            address = &((struct sockaddr_in6 *)&resolved[i])->sin6_addr;
