172	  if (strcmp(argv[1], "fixtures") == 0)
173	    {
174	      const unsigned char *data[] = {vg_audio_tone, vg_audio_speech};
175	      const size_t sizes[] = {sizeof(vg_audio_tone), sizeof(vg_audio_speech)};
176	      const char *names[] = {"/mnt/emmc/bvo04/tone.wav",
177	                             "/mnt/emmc/bvo04/speech.wav"};
178	      int i;
179	      if (mkdir("/mnt/emmc/bvo04", 0755) < 0 && errno != EEXIST)
180	        {
181	          return EXIT_FAILURE;
182	        }
183	
184	      for (i = 0; i < 2; i++)
185	        {
186	          size_t off = 0;
187	          int fd = open(names[i], O_WRONLY | O_CREAT | O_TRUNC, 0644);
188	          if (fd < 0)
189	            {
190	              return EXIT_FAILURE;
191	            }
192	
193	          while (off < sizes[i])
194	            {
195	              ssize_t n = write(fd, data[i] + off, sizes[i] - off);
196	              if (n <= 0)
197	                {
198	                  close(fd);
199	                  return EXIT_FAILURE;
200	                }
201	
202	              off += n;
203	            }
204	
205	          {
206	            int sync_result = fsync(fd);
207	            int close_result = close(fd);
208	            if (sync_result < 0 || close_result < 0)
209	              {
210	                return EXIT_FAILURE;
211	              }
212	          }
213	
214	          printf("vgaudio: fixture %s bytes=%u\n", names[i], (unsigned)off);
215	        }
216	
217	      /* Five copies of the generated 1 kHz PCM, with updated WAV lengths.
218	       * This gives stop testing a clear margin before natural completion.
219	       */
220	
221	      {
222	        unsigned char header[44];
223	        uint32_t length = 5 * (sizeof(vg_audio_tone) - sizeof(header));
224	        int ret;
225	        int fd;
226	
227	        memcpy(header, vg_audio_tone, sizeof(header));
228	        for (i = 0; i < 4; i++)
229	          {
230	            header[4 + i] = (length + 36) >> (i * 8);
231	            header[40 + i] = length >> (i * 8);
232	          }
233	
234	        fd = open("/mnt/emmc/bvo04/tone-stop.wav",
235	                  O_WRONLY | O_CREAT | O_TRUNC, 0644);
236	        if (fd < 0)
237	          {
238	            return EXIT_FAILURE;
239	          }
240	
241	        ret = vg_audio_writeall(fd, header, sizeof(header));
242	        for (i = 0; i < 5 && ret == OK; i++)
243	          {
244	            ret = vg_audio_writeall(fd, vg_audio_tone + sizeof(header),
245	                                   sizeof(vg_audio_tone) - sizeof(header));
246	          }
247	
248	        if (ret == OK && fsync(fd) < 0)
249	          {
250	            ret = -EIO;
251	          }
252	
253	        if (close(fd) < 0)
254	          {
255	            ret = -EIO;
256	          }
257	
258	        if (ret < 0)
259	          {
260	            return EXIT_FAILURE;
261	          }
262	
263	        printf("vgaudio: fixture /mnt/emmc/bvo04/tone-stop.wav bytes=%lu\n",
264	               (unsigned long)(length + sizeof(header)));
