311	  else if (strcmp(argv[1], "reg") == 0)
312	    {
313	      uint16_t val = 0;
314	      int off;
315	      int ret;
316	
317	      if (argc < 3)
318	        {
319	          vg_audio_usage();
320	          return EXIT_FAILURE;
321	        }
