121	/* ── TLS context ─────────────────────────────────────────────── */
122	
123	typedef struct {
124	    mbedtls_ssl_context ssl;
125	    mbedtls_ssl_config cfg;
126	    mbedtls_net_context net;
127	    mbedtls_ctr_drbg_context ctr_drbg;
128	    bool abort_on_close;
129	    unsigned send_pressure;
130	} tls_ctx_t;
131	
132	/* NuttX may report temporary packet-buffer pressure as ENOMEM, including
133	 * during handshake. Translate it at the BIO boundary so mbedTLS retains
134	 * the pending TLS record and the controlled poll loop applies its budget. */
135	static int tls_controlled_send(void *arg, const unsigned char *buf, size_t len)
136	{
137	    tls_ctx_t *ctx = arg;
138	    int ret = mbedtls_net_send(&ctx->net, buf, len);
139	    int error = errno;
140	    if (ret == MBEDTLS_ERR_NET_SEND_FAILED && error == ENOMEM) {
141	        if (ctx->send_pressure++ == 0)
142	            syslog(LOG_INFO, "[%s] controlled send waiting for packet buffers\n", TAG);
143	        return MBEDTLS_ERR_SSL_WANT_WRITE;
144	    }
145	    return ret;
146	}
147	
148	static int tls_controlled_recv(void *arg, unsigned char *buf, size_t len)
149	{
150	    tls_ctx_t *ctx = arg;
151	    return mbedtls_net_recv(&ctx->net, buf, len);
152	}
153	
154	static void tls_ctx_free(tls_ctx_t* ctx)
155	{
156	    if (ctx->abort_on_close) {
157	#ifdef CONFIG_NET_SOLINGER
158	        if (ctx->net.fd >= 0) {
159	            struct linger abort = {1, 0};
160	            setsockopt(ctx->net.fd, SOL_SOCKET, SO_LINGER, &abort, sizeof(abort));
161	        }
162	#endif
163	    } else {
164	        mbedtls_ssl_close_notify(&ctx->ssl);
165	    }
166	    /* close_notify already finishes TLS.  A separate shutdown followed by
167	     * close schedules overlapping TCP callbacks on NuttX, and controlled
168	     * callers used to shut down twice.  Close the socket exactly once. */
169	    mbedtls_net_close(&ctx->net);
170	    mbedtls_ssl_free(&ctx->ssl);
171	    mbedtls_ssl_config_free(&ctx->cfg);
172	    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
173	
174	#ifdef CONFIG_AI_AGENT_NET_RPMSG
175	    network_release_resource();
176	#endif
177	}
