179	/* ── Persistent connection pool (keep-alive) ─────────────────── */
180	/* Keeps one live TLS connection per host:port so repeated calls to
181	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
182	
183	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
184	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
185	#else
186	#define CONN_POOL_SIZE 2
187	#endif
188	
189	typedef struct {
190	    tls_ctx_t ctx;
191	    char host[128];
192	    char port[8];
193	    bool in_use; /* locked by a request */
194	    bool valid; /* connection is alive */
195	} conn_slot_t;
196	
197	static conn_slot_t s_pool[CONN_POOL_SIZE];
198	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
199	
200	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
201	static conn_slot_t* pool_acquire(const char* host, const char* port)
202	{
203	    pthread_mutex_lock(&s_pool_lock);
204	
205	    /* 1. Find an existing valid slot for this host:port */
206	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
207	        conn_slot_t* s = &s_pool[i];
208	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
209	            s->in_use = true;
210	            pthread_mutex_unlock(&s_pool_lock);
211	            return s;
212	        }
213	    }
214	
215	    /* 2. Find an empty slot */
216	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
217	        if (!s_pool[i].valid && !s_pool[i].in_use) {
218	            s_pool[i].in_use = true;
219	            pthread_mutex_unlock(&s_pool_lock);
220	            return &s_pool[i];
221	        }
222	    }
223	
224	    /* 3. Evict the first non-in-use slot */
225	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
226	        if (!s_pool[i].in_use) {
227	            tls_ctx_free(&s_pool[i].ctx);
228	            s_pool[i].valid = false;
229	            s_pool[i].in_use = true;
230	            pthread_mutex_unlock(&s_pool_lock);
231	            return &s_pool[i];
232	        }
233	    }
234	
235	    pthread_mutex_unlock(&s_pool_lock);
236	    return NULL; /* all slots busy — caller falls back to ephemeral */
237	}
238	
239	/* Return a slot to the pool.  keep=true means the connection is still alive. */
240	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
241	{
242	    pthread_mutex_lock(&s_pool_lock);
243	    if (keep) {
244	        strncpy(s->host, host, sizeof(s->host) - 1);
245	        strncpy(s->port, port, sizeof(s->port) - 1);
246	        s->valid = true;
247	    } else {
248	        tls_ctx_free(&s->ctx);
249	        s->valid = false;
250	        s->host[0] = '\0';
251	    }
252	    s->in_use = false;
253	    pthread_mutex_unlock(&s_pool_lock);
254	}
