256	static void tls_voice_session_clear(void);
257	
258	void vela_tls_pool_cleanup(void)
259	{
260	    tls_voice_session_clear();
261	    pthread_mutex_lock(&s_pool_lock);
262	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
263	        if (s_pool[i].in_use) {
264	            syslog(LOG_WARNING,
265	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
266	            continue;
267	        }
268	        if (s_pool[i].valid) {
269	            tls_ctx_free(&s_pool[i].ctx);
270	            s_pool[i].valid = false;
271	        }
272	        s_pool[i].host[0] = '\0';
273	    }
274	    pthread_mutex_unlock(&s_pool_lock);
275	}
