277	/* Timing is optional so the other callers (Feishu, vision, web search) keep
278	 * their current behaviour.  The marks are taken back to back, so
279	 * dns_tcp + tls_setup + tls add up to the whole connect. */
280	
281	/* Wait in short poll slices on controlled requests.  The legacy chat path
282	 * keeps its existing blocking transport when ctl is NULL. */
283	static int tls_wait_socket(int fd, short events, const vela_req_ctl_t *ctl)
284	{
285	    struct pollfd pfd = { .fd = fd, .events = events };
286	    uint32_t started = agent_mono_ms();
287	
288	    for (;;) {
289	        uint32_t now = agent_mono_ms();
290	        uint32_t slice;
291	        int ret;
292	
293	        if (vela_req_cancelled(ctl)) {
294	            return VELA_TLS_ERR_CANCELLED;
295	        }
296	        if (vela_req_budget_ms(ctl, now) == 0
297	            || agent_elapsed_ms(started, now) >= 60000) {
298	            return VELA_TLS_ERR_TIMEOUT;
299	        }
300	        slice = vela_req_io_timeout_ms(ctl, now, 100);
301	        ret = poll(&pfd, 1, (int)slice);
302	        if (ret > 0) {
303	            return (pfd.revents & POLLNVAL) ? VELA_TLS_ERR_CONNECT : 0;
304	        }
305	        if (ret < 0 && errno != EINTR) {
306	            return VELA_TLS_ERR_CONNECT;
307	        }
308	    }
309	}
