124	  printf("vgaudio: SAI2_A cr1=0x%08lx gcr=0x%08lx\n",
125	         (unsigned long)cr1, (unsigned long)gcr);
126	  printf("vgaudio: mode=%s nodiv=%lu mckdiv=%lu reserved27=%lu saien=%lu\n",
127	         modes[mode],
128	         (unsigned long)((cr1 >> 19) & 1),
129	         (unsigned long)mckdiv,
130	         (unsigned long)((cr1 >> 27) & 1),
131	         (unsigned long)((cr1 >> 16) & 1));
132	
133	  if (mckdiv != 0)
134	    {
135	      printf("vgaudio: current MCLK = 49142857 / %lu = %lu Hz (inferred)\n",
136	             (unsigned long)mckdiv, (unsigned long)(49142857u / mckdiv));
137	    }
138	  {
139	    uint32_t r[20] = {0};
140	    if (stm32_audio_tx_record(r, 20) == OK)
141	      {
142	        printf("vgaudio: last dma=%lx sr=%lx cr1=%lx frcr=%lx slots=%lx "
143	               "count=%lu addr=%lx\n", (unsigned long)r[0],
144	               (unsigned long)r[1], (unsigned long)r[2],
145	               (unsigned long)r[3], (unsigned long)r[4],
146	               (unsigned long)r[7], (unsigned long)r[9]);
147	        printf("vgaudio: dma_done=%lu errors=%lu timeouts=%lu txbytes=%lu\n",
148	               (unsigned long)r[11], (unsigned long)r[12],
149	               (unsigned long)r[13], (unsigned long)r[14]);
150	        printf("vgaudio: sai_underruns=%lu clockerrors=%lu\n",
151	               (unsigned long)r[15], (unsigned long)r[16]);
152	        printf("vgaudio: stream_ms=%lu stream_bytes=%lu tick_us=%lu\n",
153	               (unsigned long)r[17], (unsigned long)r[18],
154	               (unsigned long)r[19]);
155	      }
156	  }
