400	     * Numeric address/service conversion cannot initiate another DNS query.
401	     * Other platforms retain their platform resolver. */
402	    hints.ai_socktype = SOCK_STREAM;
403	    hints.ai_family = AF_UNSPEC;
404	#if defined(__NuttX__) && defined(CONFIG_NETDB_DNSCLIENT)
405	    int ret = tls_resolve_controlled(host, port, &hints, &addresses, ctl);
406	#else
407	    int ret = getaddrinfo(host, port, &hints, &addresses);
408	#endif
409	    if (vela_req_cancelled(ctl)) {
410	        result = VELA_TLS_ERR_CANCELLED;
411	        goto out;
412	    }
413	    if (vela_req_budget_ms(ctl, agent_mono_ms()) == 0) {
414	        result = VELA_TLS_ERR_TIMEOUT;
415	        goto out;
416	    }
417	    if (ret != 0) {
418	        goto out;
419	    }
420	
421	    for (a = addresses; a != NULL; a = a->ai_next) {
422	        int flags;
423	        int error = 0;
424	        socklen_t error_len = sizeof(error);
425	
426	        ctx->net.fd = socket(a->ai_family, a->ai_socktype, a->ai_protocol);
427	        if (ctx->net.fd < 0) {
428	            syslog(LOG_ERR, "[%s] socket allocation failed errno=%d\n", TAG, errno);
429	            continue;
430	        }
431	        flags = fcntl(ctx->net.fd, F_GETFL, 0);
432	        if (flags < 0 || fcntl(ctx->net.fd, F_SETFL, flags | O_NONBLOCK) < 0) {
433	            goto next;
434	        }
435	        ret = connect(ctx->net.fd, a->ai_addr, a->ai_addrlen);
436	        if (ret == 0) {
437	            result = 0;
438	            break;
439	        }
440	        if (errno != EINPROGRESS && errno != EWOULDBLOCK && errno != EALREADY) {
441	            goto next;
442	        }
443	        ret = tls_wait_socket(ctx->net.fd, POLLOUT, ctl);
444	        if (ret != 0) {
445	            result = ret;
446	            break;
447	        }
448	        if (getsockopt(ctx->net.fd, SOL_SOCKET, SO_ERROR, &error, &error_len) == 0
449	            && error == 0) {
450	            result = 0;
451	            break;
452	        }
453	next:
454	        mbedtls_net_close(&ctx->net);
455	    }
456	out:
457	    if (addresses != NULL) {
458	        freeaddrinfo(addresses);
459	    }
460	#if defined(__NuttX__) && defined(CONFIG_NETDB_DNSCLIENT) && defined(CONFIG_VG_HMI)
461	    if (result != 0 && host != NULL && strcmp(host, "token-plan-cn.xiaomimimo.com") == 0) {
462	        pthread_mutex_lock(&voice_dns_lock);
463	        voice_dns_count = 0;
464	        pthread_mutex_unlock(&voice_dns_lock);
465	    }
466	#endif
467	    return result;
468	}
