470	/* 仅对 HMI 已知服务的受控连接缓存 TLS 1.2 会话，恢复资格一分钟后失效。
471	 * 不保存到文件，不缓存 HTTP 凭据；服务端可拒绝恢复并执行完整握手。 */
472	#if defined(CONFIG_VG_HMI) && defined(CONFIG_VG_VOICE_TLS_CACHE) && defined(MBEDTLS_SSL_CLI_C)
473	static pthread_mutex_t voice_session_lock = PTHREAD_MUTEX_INITIALIZER;
474	static mbedtls_ssl_session voice_session;
475	static pthread_once_t voice_session_once = PTHREAD_ONCE_INIT;
476	static bool voice_session_valid;
477	static uint32_t voice_session_saved;
478	
479	static bool tls_voice_session_target(const char *host, const char *port,
480	                                     const vela_req_ctl_t *ctl)
481	{
482	    return ctl != NULL && host != NULL && port != NULL &&
483	        strcmp(host, "token-plan-cn.xiaomimimo.com") == 0 && strcmp(port, "443") == 0;
484	}
485	
486	static void tls_voice_session_init_once(void)
487	{
488	    mbedtls_ssl_session_init(&voice_session);
489	}
490	
491	static void tls_voice_session_clear(void)
492	{
493	    pthread_once(&voice_session_once, tls_voice_session_init_once);
494	    pthread_mutex_lock(&voice_session_lock);
495	    mbedtls_ssl_session_free(&voice_session);
496	    mbedtls_ssl_session_init(&voice_session);
497	    voice_session_valid = false;
498	    pthread_mutex_unlock(&voice_session_lock);
499	}
500	
501	static bool tls_voice_session_offer(mbedtls_ssl_context *ssl, const char *host,
502	                                    const char *port, const vela_req_ctl_t *ctl,
503	                                    uint32_t now)
504	{
505	    if (!tls_voice_session_target(host, port, ctl)) return false;
506	    pthread_once(&voice_session_once, tls_voice_session_init_once);
507	    pthread_mutex_lock(&voice_session_lock);
508	    bool offered = false;
509	    if (voice_session_valid && (uint32_t)(now - voice_session_saved) >= 60000) {
510	        mbedtls_ssl_session_free(&voice_session);
511	        mbedtls_ssl_session_init(&voice_session);
512	        voice_session_valid = false;
513	    }
514	    if (voice_session_valid) offered = mbedtls_ssl_set_session(ssl, &voice_session) == 0;
515	    pthread_mutex_unlock(&voice_session_lock);
516	    return offered;
517	}
518	
519	static void tls_voice_session_save(mbedtls_ssl_context *ssl, const char *host,
520	                                   const char *port, const vela_req_ctl_t *ctl,
521	                                   uint32_t now)
522	{
523	    if (!tls_voice_session_target(host, port, ctl) ||
524	        strcmp(mbedtls_ssl_get_version(ssl), "TLSv1.2") != 0) return;
525	    pthread_once(&voice_session_once, tls_voice_session_init_once);
526	    pthread_mutex_lock(&voice_session_lock);
527	    mbedtls_ssl_session_free(&voice_session);
528	    mbedtls_ssl_session_init(&voice_session);
529	    voice_session_valid = mbedtls_ssl_get_session(ssl, &voice_session) == 0;
530	    voice_session_saved = now;
531	    pthread_mutex_unlock(&voice_session_lock);
532	}
