537	static int tls_ctx_connect(tls_ctx_t* ctx, const char* host, const char* port,
538	    agent_llm_timing_t* timing, const vela_req_ctl_t *ctl)
539	{
540	    int ret;
541	    uint32_t mark = agent_mono_ms();
542	
543	    ctx->abort_on_close = ctl != NULL;
544	    ctx->send_pressure = 0;
545	    mbedtls_ssl_init(&ctx->ssl);
546	    mbedtls_ssl_config_init(&ctx->cfg);
547	    mbedtls_net_init(&ctx->net);
548	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
549	
550	    /* Seed RNG directly with our robust function */
551	    const char* pers = "vela_tls";
552	    if ((ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, simple_entropy_func, NULL,
553	             (const unsigned char*)pers,
554	             strlen(pers)))
555	        != 0) {
556	        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=0x%x\n", TAG, -ret);
557	        if (timing != NULL) {
558	            timing->tls_setup_ms = agent_lap_ms(&mark);
559	        }
560	        return VELA_TLS_ERR_HANDSHAKE;
561	    }
562	
563	    /* Check system time — crucial for TLS certificate validation. */
564	    time_t now = time(NULL);
565	    syslog(LOG_DEBUG, "[%s] Handshake start: Host=%s, UNIX=%ld\n", TAG, host, (long)now);
566	
567	    if (now < 1704067200) { /* Jan 1 2024 */
568	        syslog(LOG_WARNING, "[%s] Clock too old, forcing to 2026\n", TAG);
569	        struct timespec ts = { .tv_sec = 1772275200, .tv_nsec = 0 };
570	        clock_settime(CLOCK_REALTIME, &ts);
571	    }
572	
573	    if (timing != NULL) {
574	        timing->tls_setup_ms = agent_lap_ms(&mark);
575	    }
576	
577	    /* TCP connect — use HTTP CONNECT proxy if configured */
578	#ifdef CONFIG_AI_AGENT_NET_RPMSG
579	    {
580	        int res_ret = network_acquire_resource(network_get_connect_timeout() * 1000);
581	        if (res_ret != 0) {
582	            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
583	            return VELA_TLS_ERR_CONNECT;
584	        }
585	    }
586	#endif
587	
588	    if (http_proxy_is_enabled()) {
589	        if (timing != NULL) {
590	            /* The tunnel also covers reaching the proxy, so the phase is
591	             * still one combined connect.  The LLM layer marks the proxy
592	             * path separately when it sees http_proxy_is_enabled(). */
593	
594	            timing->fused_dns_tcp = true;
595	        }
596	
597	        /* The proxy tunnel has a separate blocking contract.  Controlled
598	         * callers must fail explicitly rather than silently lose the budget. */
599	        if (ctl != NULL) {
600	            return VELA_TLS_ERR_CONNECT;
601	        }
602	        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
603	        if (tunnel_fd < 0) {
604	            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
605	                TAG, host, port);
606	            return VELA_TLS_ERR_CONNECT;
607	        }
608	        ctx->net.fd = tunnel_fd;
609	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
610	            TAG, tunnel_fd, host, port);
611	    } else {
612	        ret = ctl != NULL ? tls_connect_controlled(ctx, host, port, ctl)
613	                          : mbedtls_net_connect(&ctx->net, host, port,
614	                                MBEDTLS_NET_PROTO_TCP);
615	
616	        /* The connect time is recorded before looking at the result.  It
617	         * used to be recorded only on success, so a connect that burned 81 s
618	         * of SYN retries before failing left dns_tcp at na and the wait
619	         * appeared only in the http total.  A failed connect is still a
620	         * measured connect. */
621	
622	        if (timing != NULL) {
623	            timing->dns_tcp_ms = agent_lap_ms(&mark);
624	            timing->fused_dns_tcp = true;
625	        }
626	
627	        if (ret != 0) {
628	            syslog(LOG_ERR, "[%s] net_connect %s:%s ret=0x%x\n",
629	                TAG, host, port, -ret);
630	            return ctl != NULL ? ret : VELA_TLS_ERR_CONNECT;
631	        }
632	    }
633	
634	    if (timing != NULL && timing->dns_tcp_ms == AGENT_T_NA) {
635	        /* Proxy path: the tunnel call above also covers reaching the proxy,
636	         * so it is one combined connect. */
637	
638	        timing->dns_tcp_ms = agent_lap_ms(&mark);
639	        timing->fused_dns_tcp = true;
640	    }
641	
642	    /* Force blocking mode and set socket-level read timeout.
643	     * This avoids using select()/poll() inside mbedtls_net_recv_timeout
644	     * which returns MBEDTLS_ERR_NET_POLL_FAILED (-0x0047) on NuttX/QEMU.
645	     * Timeout is configured via AGENT_LLM_SOCKET_TIMEOUT_SEC in
646	     * agent_config.h.  LLM APIs (especially kimi with thinking mode)
647	     * can take over 60s for long responses. */
648	    if (ctl == NULL) {
649	        mbedtls_net_set_block(&ctx->net);
650	    } else if (mbedtls_net_set_nonblock(&ctx->net) != 0) {
651	        return VELA_TLS_ERR_CONNECT;
652	    }
653	    if (ctx->net.fd >= 0) {
654	#ifdef CONFIG_AI_AGENT_NET_RPMSG
655	        int read_timeout_sec = network_get_read_timeout();
656	        struct timeval tv = { .tv_sec = read_timeout_sec, .tv_usec = 0 };
657	#else
658	        struct timeval tv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
659	            .tv_usec = 0 };
660	#endif
661	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
662	
663	#ifdef CONFIG_AI_AGENT_NET_RPMSG
664	        {
665	            int timeout_sec = network_get_connect_timeout();
666	            struct timeval ctv = { .tv_sec = timeout_sec, .tv_usec = 0 };
667	            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
668	        }
669	#endif
670	    }
671	
672	    /* SSL config: client, TLS, default ciphersuites */
673	    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
674	             MBEDTLS_SSL_IS_CLIENT,
675	             MBEDTLS_SSL_TRANSPORT_STREAM,
676	             MBEDTLS_SSL_PRESET_DEFAULT))
677	        != 0) {
678	        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=0x%x\n", TAG, -ret);
679	        return VELA_TLS_ERR_HANDSHAKE;
680	    }
681	
682	    /* Pin the TLS version range to what is actually compiled in.
683	     * Setting max to MBEDTLS_SSL_VERSION_TLS1_3 when MBEDTLS_SSL_PROTO_TLS1_3
684	     * is not defined causes mbedtls_ssl_setup() to return BAD_CONFIG (-0x5e80).
685	     * Use TLS 1.3 as the ceiling only when the library was built with TLS 1.3
686	     * support; otherwise cap at TLS 1.2. */
687	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
688	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
689	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
690	#else
691	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
692	#endif
693	
694	    /* Advertise ALPN so Cloudflare/OpenAI servers don't silently reject us.
695	     * Modern HTTPS servers send a fatal TLS alert or close the connection
696	     * when no ALPN extension is present in the ClientHello.
697	     * MBEDTLS_SSL_ALPN must be enabled in the build (it is). */
698	#if defined(MBEDTLS_SSL_ALPN)
699	    static const char* alpn_protos[] = { "http/1.1", NULL };
700	    if ((ret = mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn_protos)) != 0) {
701	        syslog(LOG_WARNING, "[%s] Failed to set ALPN protocols: -0x%04x (non-fatal)\n", TAG, -ret);
702	    }
703	#endif
704	
705	    /* Skip full chain verification — keeps portability without CA bundle */
706	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
707	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
708	
709	    /* Read timeout is handled at the socket level via SO_RCVTIMEO,
710	     * not via mbedtls_ssl_conf_read_timeout + mbedtls_net_recv_timeout,
711	     * because select()/poll() inside mbedtls_net_recv_timeout fails on
712	     * NuttX/QEMU with MBEDTLS_ERR_NET_POLL_FAILED (-0x0047). */
713	
714	    if ((ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg)) != 0) {
715	        syslog(LOG_ERR, "[%s] ssl_setup ret=0x%x\n", TAG, -ret);
716	        return VELA_TLS_ERR_HANDSHAKE;
717	    }
718	
719	    if ((ret = mbedtls_ssl_set_hostname(&ctx->ssl, host)) != 0) {
720	        syslog(LOG_ERR, "[%s] ssl_set_hostname ret=0x%x\n", TAG, -ret);
721	        return VELA_TLS_ERR_HANDSHAKE;
722	    }
723	
724	#if defined(CONFIG_VG_HMI) && defined(CONFIG_VG_VOICE_TLS_CACHE) && defined(MBEDTLS_SSL_CLI_C)
725	    bool session_offered = tls_voice_session_offer(&ctx->ssl, host, port, ctl, agent_mono_ms());
726	#endif
727	
728	    /* Use blocking recv — no select()/poll().  The read
729	     * timeout is enforced by the SO_RCVTIMEO socket option set above. */
730	    if (ctl != NULL) {
731	        mbedtls_ssl_set_bio(&ctx->ssl, ctx,
732	            tls_controlled_send, tls_controlled_recv, NULL);
733	    } else {
734	        mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
735	            mbedtls_net_send, mbedtls_net_recv, NULL);
736	    }
737	
738	    /* Timer for the handshake starts here, after configuration.  Setup cost
739	     * is already accounted for in tls_setup_ms so the two do not overlap. */
740	
741	    mark = agent_mono_ms();
742	
743	    /* Handshake */
744	    for (;;) {
745	        if (ctl != NULL) {
746	            if (vela_req_cancelled(ctl)) {
747	                return VELA_TLS_ERR_CANCELLED;
748	            }
749	            if (vela_req_budget_ms(ctl, agent_mono_ms()) == 0) {
750	                return VELA_TLS_ERR_TIMEOUT;
751	            }
752	        }
753	        ret = mbedtls_ssl_handshake(&ctx->ssl);
754	        if (ret == 0) {
755	            break;
756	        }
757	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
758	#if defined(MBEDTLS_ERROR_C)
759	            char err_buf[128];
760	            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
761	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n", TAG, -ret, err_buf);
762	#else
763	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", TAG, -ret);
764	#endif
765	            /* Log if it was a fatal alert */
766	            if (ret == MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE) {
767	                syslog(LOG_ERR, "[%s] Server sent fatal alert message\n", TAG);
768	            }
769	
770	            /* A handshake that failed after waiting is still a measured
771	             * handshake; leaving tls at na would put its time nowhere. */
772	
773	            if (timing != NULL) {
774	                timing->tls_ms = agent_lap_ms(&mark);
775	            }
776	#if defined(CONFIG_VG_HMI) && defined(CONFIG_VG_VOICE_TLS_CACHE) && defined(MBEDTLS_SSL_CLI_C)
777	            if (session_offered) tls_voice_session_clear();
778	#endif
779	            return VELA_TLS_ERR_HANDSHAKE;
780	        }
781	        if (ctl != NULL) {
782	            ret = tls_wait_socket(ctx->net.fd,
783	                ret == MBEDTLS_ERR_SSL_WANT_READ ? POLLIN : POLLOUT, ctl);
784	            if (ret != 0) {
785	                return ret;
786	            }
787	        }
788	    }
789	
790	#if defined(CONFIG_VG_HMI) && defined(CONFIG_VG_VOICE_TLS_CACHE) && defined(MBEDTLS_SSL_CLI_C)
791	    uint32_t handshake_ms = agent_elapsed_ms(mark, agent_mono_ms());
792	#endif
793	    if (timing != NULL) {
794	        timing->tls_ms = agent_lap_ms(&mark);
795	    }
796	
797	#if defined(CONFIG_VG_HMI) && defined(CONFIG_VG_VOICE_TLS_CACHE) && defined(MBEDTLS_SSL_CLI_C)
798	    if (tls_voice_session_target(host, port, ctl)) {
799	        syslog(LOG_INFO, "[%s] voice session offered=%u handshake_ms=%u\n", TAG,
800	            session_offered, (unsigned)handshake_ms);
801	        tls_voice_session_save(&ctx->ssl, host, port, ctl, agent_mono_ms());
802	    }
803	#endif
804	
805	    syslog(LOG_INFO, "[%s] Handshake OK: %s / %s\n", TAG, mbedtls_ssl_get_version(&ctx->ssl),
806	        mbedtls_ssl_get_ciphersuite(&ctx->ssl));
807	
808	    return 0;
809	}
810	
811	/* ── HTTP/1.1 framing ────────────────────────────────────────── */
812	
813	/* mbedtls_ssl_write() wrapper that survives a full socket send buffer.
814	 *
815	 * tls_ctx_connect() puts the socket in blocking mode and leaves it there, and
816	 * mbedtls' net_would_block() refuses to report a would-block condition on a
817	 * blocking socket ("Never return 'WOULD BLOCK' on a blocking socket").  A
818	 * send() that meets a full TCP send buffer therefore reaches us as
819	 * MBEDTLS_ERR_NET_SEND_FAILED instead of MBEDTLS_ERR_SSL_WANT_WRITE, which
820	 * used to abort a ~16 KB LLM request body right after a healthy handshake.
821	 *
822	 * Keep each record small and treat a short or failed send as retryable for a
823	 * bounded budget.  Retrying is safe: mbedtls keeps the unsent tail in
824	 * ssl->out_left and flushes it before encrypting anything new. */
825	
826	#define TLS_WRITE_CHUNK      4096
827	#define TLS_WRITE_ATTEMPTS   64
828	#define TLS_WRITE_BACKOFF_US 20000
829	
830	/* A send that failed because the socket is gone must not be retried: the
831	 * peer closed the connection and every retry waits for a timeout that
832	 * cannot succeed.  NuttX reports these as ENOTCONN, EPIPE, ECONNRESET or
833	 * EBADF.  ENOMEM is the opposite case: the stack ran out of packet buffers
834	 * and the send becomes possible again once the peer acknowledges. */
835	static bool tls_send_error_is_fatal(int err)
836	{
837	    switch (err)
838	    {
839	        case ENOTCONN:
840	        case EPIPE:
841	        case ECONNRESET:
842	        case EBADF:
843	        case ENOTSOCK:
844	            return true;
845	        default:
846	            return false;
847	    }
848	}
849	
850	static int tls_ssl_write_all(tls_ctx_t* ctx, const char* what,
851	    const unsigned char* buf, size_t len)
852	{
853	    size_t off = 0;
854	    int attempts = 0;
855	
856	    while (off < len) {
857	        size_t chunk = len - off;
858	        int ret;
859	
860	        if (chunk > TLS_WRITE_CHUNK) {
861	            chunk = TLS_WRITE_CHUNK;
862	        }
863	
864	        ret = mbedtls_ssl_write(&ctx->ssl, buf + off, chunk);
865	        if (ret > 0) {
866	            off += (size_t)ret;
867	            attempts = 0;
868	            continue;
869	        }
870	
871	        if (ret == 0) {
872	            syslog(LOG_ERR, "[%s] %s write stalled at %u/%u\n",
873	                TAG, what, (unsigned)off, (unsigned)len);
874	            return VELA_TLS_ERR_WRITE;
875	        }
876	
877	        attempts++;
878	        {
879	            int err = errno;
880	
881	            /* The connection is gone: retrying only burns the budget. */
882	
883	            if (tls_send_error_is_fatal(err)) {
884	                syslog(LOG_ERR,
885	                    "[%s] %s write failed at %u/%u ret=-0x%04x errno=%d (connection gone)\n",
886	                    TAG, what, (unsigned)off, (unsigned)len, -ret, err);
887	                return VELA_TLS_ERR_WRITE;
888	            }
889	
890	            if (attempts == 1 || attempts >= TLS_WRITE_ATTEMPTS) {
891	                int fl = (ctx->net.fd >= 0) ? fcntl(ctx->net.fd, F_GETFL) : -1;
892	
893	                syslog(attempts == 1 ? LOG_WARNING : LOG_ERR,
894	                    "[%s] %s write retry %d at %u/%u ret=-0x%04x errno=%d fl=0x%x\n",
895	                    TAG, what, attempts, (unsigned)off, (unsigned)len,
896	                    -ret, err, (unsigned)fl);
897	            }
898	        }
899

900	        if (attempts >= TLS_WRITE_ATTEMPTS) {
901	            return VELA_TLS_ERR_WRITE;
902	        }
903	
904	        /* Wait for the socket to take data again.  A closed peer reports an
905	         * error event immediately instead of after the full backoff. */
906	
907	        {
908	            struct pollfd pfd = { .fd = ctx->net.fd, .events = POLLOUT };
909	            int pr = poll(&pfd, 1, TLS_WRITE_BACKOFF_US / 1000);
910	
911	            if (pr > 0 && (pfd.revents & (POLLERR | POLLHUP | POLLNVAL)) != 0) {
912	                syslog(LOG_ERR, "[%s] %s write sees a dead socket at %u/%u\n",
913	                    TAG, what, (unsigned)off, (unsigned)len);
914	                return VELA_TLS_ERR_WRITE;
915	            }
916	        }
917	    }
918	
919	    return 0;
920	}
921	
922	static int tls_write_request(tls_ctx_t* ctx,
923	    const char* method, const char* host,
924	    const char* path,
925	    const vela_header_t* headers,
926	    const char* body, size_t body_len)
927	{
928	    /* Heap-allocate header buffer to reduce stack pressure.
929	     * This function is called from threads with limited stack
930	     * (outbound dispatch 16KB) and the TLS context already
931	     * consumes significant stack space. */
932	    char* hdr = malloc(4096);
933	    if (!hdr)
934	        return VELA_TLS_ERR_OVERFLOW;
935	
936	    int pos = 0;
937	
938	#define HDR_APPEND(fmt, ...)                                    \
939	    pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
940	    if (pos >= 4096) {                                          \
941	        free(hdr);                                              \
942	        return VELA_TLS_ERR_OVERFLOW;                           \
943	    }
944	
945	    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
946	    HDR_APPEND("Host: %s\r\n", host);
947	    HDR_APPEND("Connection: keep-alive\r\n");
948	    HDR_APPEND("User-Agent: agent-vela/1.0\r\n");
949	
950	    if (body && body_len > 0) {
951	        HDR_APPEND("Content-Length: %zu\r\n", body_len);
952	    }
953	
954	    if (headers) {
955	        for (const vela_header_t* h = headers; h->name != NULL; h++) {
956	            HDR_APPEND("%s: %s\r\n", h->name, h->value);
957	        }
958	    }
959	
960	    HDR_APPEND("\r\n");
961	#undef HDR_APPEND
962	
963	    /* Write headers */
964	    if (tls_ssl_write_all(ctx, "hdr",
965	            (const unsigned char*)hdr, (size_t)pos) != 0) {
966	        free(hdr);
967	        return VELA_TLS_ERR_WRITE;
968	    }
969	
970	    free(hdr);
971	
972	    /* Write body */
973	    if (body && body_len > 0) {
974	        if (tls_ssl_write_all(ctx, "body",
975	                (const unsigned char*)body, body_len) != 0) {
976	            return VELA_TLS_ERR_WRITE;
977	        }
978	    }
979	
980	    return 0;
981	}
982	
983	/**
984	 * Read full HTTP/1.1 response.
985	 * Returns HTTP status code; writes body into resp_buf (NUL-terminated).
986	 * Handles Transfer-Encoding: chunked and Content-Length.
987	 */
988	#define TLS_RAW_BUF_SIZE 8192  /* 8KB: enough for HTTP headers + initial body */
989	
990	/* Receive progress: a gap at or above this many milliseconds between reads is
991	 * recorded, up to VELA_TLS_PROGRESS_MAX entries.  Below the gap limit the
992	 * reply is arriving steadily and needs no per-read trace. */
993	
994	#define VELA_TLS_PROGRESS_GAP_MS 1000
995	#define VELA_TLS_PROGRESS_MAX    8
996	
997	/* Number of static raw buffers — at most 2, scaled to pool size.
998	 * Each buffer is 8KB; pool=1 uses 1 buffer, pool>=2 uses 2. */
999	#define TLS_RAW_BUF_COUNT (CONN_POOL_SIZE < 2 ? 1 : 2)
1000	
1001	static char s_tls_raw_buf[TLS_RAW_BUF_COUNT][TLS_RAW_BUF_SIZE];
1002	static pthread_mutex_t s_tls_raw_lock[TLS_RAW_BUF_COUNT];
1003	static pthread_once_t s_tls_raw_once = PTHREAD_ONCE_INIT;
1004	
1005	static void tls_raw_init_once(void)
1006	{
1007	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
1008	        pthread_mutex_init(&s_tls_raw_lock[i], NULL);
1009	    }
1010	}
1011	
1012	static char* tls_raw_acquire(void)
1013	{
1014	    pthread_once(&s_tls_raw_once, tls_raw_init_once);
1015	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
1016	        if (pthread_mutex_trylock(&s_tls_raw_lock[i]) == 0) {
1017	            return s_tls_raw_buf[i];
1018	        }
1019	    }
1020	    /* All busy — block on first */
1021	    pthread_mutex_lock(&s_tls_raw_lock[0]);
1022	    return s_tls_raw_buf[0];
1023	}
1024	
1025	static void tls_raw_release(char* buf)
1026	{
1027	    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
1028	        if (buf == s_tls_raw_buf[i]) {
1029	            pthread_mutex_unlock(&s_tls_raw_lock[i]);
1030	            return;
1031	        }
1032	    }
1033	}
1034	
1035	/* t0 is the moment the request finished sending, so ttfb_ms covers the
1036	 * server's wait before the first response byte.  The first byte is the
1037	 * status line: this path is not streamed, so it is not a model token. */
1038	
1039	static int tls_read_response(tls_ctx_t* ctx, char* resp_buf, size_t resp_cap,
1040	    size_t* out_body_len, bool* out_keep_alive, uint32_t t0,
1041	    agent_llm_timing_t* timing)
1042	{
1043	    /* Use static buffers to avoid heap fragmentation */
1044	    char* raw = tls_raw_acquire();
1045	    size_t raw_len = 0;
1046	    int eof = 0;
1047	    int ret;
1048	    bool first_byte_seen = false;
1049	
1050	    /* Receive progress.  A reply that delivers its body in one or two reads
1051	     * leaves gaps at zero and prints nothing. */
1052	
1053	    uint32_t last_read_ms = t0;
1054	    uint32_t first_read_ms = 0;
1055	    int gaps = 0;
1056	    int32_t progress_gap[VELA_TLS_PROGRESS_MAX];
1057	    uint32_t progress_at[VELA_TLS_PROGRESS_MAX];
1058	    uint32_t progress_bytes[VELA_TLS_PROGRESS_MAX];
1059	
1060	    /* Read until we have the full header (double CRLF) or buffer full */
1061	    while (!eof && raw_len < TLS_RAW_BUF_SIZE - 1) {
1062	        ret = mbedtls_ssl_read(&ctx->ssl,
1063	            (unsigned char*)(raw + raw_len),
1064	            TLS_RAW_BUF_SIZE - 1 - raw_len);
1065	        if (ret > 0 && !first_byte_seen) {
1066	            first_byte_seen = true;
1067	            if (timing != NULL) {
1068	                timing->ttfb_ms = agent_elapsed_ms(t0, agent_mono_ms());
1069	            }
1070	        }
1071	
1072	        if (ret > 0) {
1073	            raw_len += (size_t)ret;
1074	            if (memmem(raw, raw_len, "\r\n\r\n", 4))
1075	                break;
1076	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1077	            eof = 1;
1078	            break;
1079	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
1080	            syslog(LOG_ERR, "[%s] ssl_read (header) ret=0x%x\n", TAG, -ret);
1081	            tls_raw_release(raw);
1082	            return VELA_TLS_ERR_READ;
1083	        }
1084	    }
1085	    raw[raw_len] = '\0';
1086	
1087	    /* Parse status line */
1088	    int http_status = 0;
1089	    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
1090	        syslog(LOG_ERR, "[%s] Failed to parse HTTP status from: %.80s\n", TAG, raw);
1091	        tls_raw_release(raw);
1092	        return VELA_TLS_ERR_READ;
1093	    }
1094	
1095	    /* Find header/body split */
1096	    char* body_start = (char*)memmem(raw, raw_len, "\r\n\r\n", 4);
1097	    if (!body_start) {
1098	        resp_buf[0] = '\0';
1099	        tls_raw_release(raw);
1100	        return http_status;
1101	    }
1102	
1103	    /* Determine keep-alive from Connection header (default true for HTTP/1.1) */
1104	    if (out_keep_alive) {
1105	        *out_keep_alive = true;  /* HTTP/1.1 default */
1106	        char* conn_hdr = strcasestr(raw, "Connection:");
1107	        if (conn_hdr && conn_hdr < body_start) {
1108	            *out_keep_alive = (strcasestr(conn_hdr, "keep-alive") != NULL);
1109	        }
1110	    }
1111	    body_start += 4; /* skip double CRLF */
1112	
1113	    /* Extract content-length if present */
1114	    long content_length = -1;
1115	    {
1116	        char* cl_hdr = strcasestr(raw, "Content-Length:");
1117	        if (cl_hdr && cl_hdr < body_start) {
1118	            cl_hdr += strlen("Content-Length:");
1119	            content_length = strtol(cl_hdr, NULL, 10);
1120	            if (content_length < 0 || content_length > 10 * 1024 * 1024) {
1121	                content_length = -1; /* reject absurd values */
1122	            }
1123	        }
1124	    }
1125	    int chunked = 0;
1126	    {
1127	        char* te_hdr = strcasestr(raw, "Transfer-Encoding:");
1128	        if (te_hdr && te_hdr < body_start) {
1129	            chunked = (strcasestr(te_hdr, "chunked") != NULL);
1130	        }
1131	    }
1132	
1133	    /* Initial fragment already in raw buffer */
1134	    size_t initial = (size_t)(raw + raw_len - body_start);
1135	    size_t resp_pos = 0;
1136	
1137	    /* Copy initial fragment */
1138	    size_t copy = initial < resp_cap - 1 ? initial : resp_cap - 1;
1139	    memcpy(resp_buf, body_start, copy);
1140	    resp_pos = copy;
1141	
1142	    /* Keep reading body.
1143	     *
1144	     * The end condition depends on how the response is framed.  Before this
1145	     * only Content-Length was honoured, so a chunked reply on a keep-alive
1146	     * connection kept reading after its terminating chunk until the socket
1147	     * timed out.  vela_http_body_complete() applies RFC 9112 6.3: chunked
1148	     * ends at the zero chunk, Content-Length ends at its count, and an
1149	     * unframed reply ends when the peer closes.
1150	     *
1151	     * Completeness is tested before every read, including the first, because
1152	     * the initial fragment copied above may already hold the whole body.  A
1153	     * read issued after that would wait for bytes that will never arrive. */
1154	
1155	    while (!eof && resp_pos < resp_cap - 1) {
1156	        if (vela_http_body_complete(chunked, content_length, resp_pos,
1157	                resp_buf)) {
1158	            break;
1159	        }
1160	        ret = mbedtls_ssl_read(&ctx->ssl,
1161	            (unsigned char*)(resp_buf + resp_pos),
1162	            resp_cap - 1 - resp_pos);
1163	        if (ret > 0) {
1164	            resp_pos += (size_t)ret;
1165	
1166	            /* Receive progress for slow replies.
1167	             *
1168	             * A body that takes minutes can be arriving steadily, arriving in
1169	             * bursts after long silences, or already complete while the caller
1170	             * waits on something else.  Reporting cumulative bytes with the
1171	             * gap since the previous read separates those without logging any
1172	             * content.  Only replies that pass the threshold are traced, so a
1173	             * normal round stays quiet. */
1174	
1175	            uint32_t now = agent_mono_ms();
1176	
1177	            if (gaps == 0 && first_read_ms == 0) {
1178	                first_read_ms = now;
1179	            }
1180	
1181	            /* Idle is measured from the previous read inside this loop, not
1182	             * from t0.  On the first iteration last_read_ms is still t0, so
1183	             * the initial server wait would be counted twice: once as ttfb
1184	             * and again as a body gap.  Seed it at the first byte instead. */
1185	
1186	            if (last_read_ms == t0) {
1187	                last_read_ms = now;
1188	            }
1189	
1190	            int32_t idle = agent_elapsed_ms(last_read_ms, now);
1191	
1192	            if (idle >= VELA_TLS_PROGRESS_GAP_MS) {
1193	                if (gaps < VELA_TLS_PROGRESS_MAX) {
1194	                    progress_gap[gaps] = idle;
1195	                    progress_at[gaps] = agent_elapsed_ms(t0, now);
1196	                    progress_bytes[gaps] = (uint32_t)resp_pos;
1197	                }
1198	                gaps++;
1199	            }
1200	
1201	            last_read_ms = now;
1202	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1203	            break;
1204	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
1205	            break;
1206	        }
1207	    }
1208	
1209	    /* One line per slow reply.  deltas says how many gaps were seen, which
1210	     * can exceed the stored entries; the entries are the worst ones seen
1211	     * first, so a truncated list still shows the shape of the wait. */
1212	
1213	    if (timing != NULL && gaps > 0) {
1214	        int shown = gaps < VELA_TLS_PROGRESS_MAX ? gaps : VELA_TLS_PROGRESS_MAX;
1215	
1216	        syslog(LOG_INFO,
1217	            "[%s] body progress: gaps=%d first_read=%ldms total=%u bytes\n",
1218	            TAG, gaps,
1219	            (long)agent_elapsed_ms(t0, first_read_ms), (unsigned)resp_pos);
1220	
1221	        for (int i = 0; i < shown; i++) {
1222	            syslog(LOG_INFO,
1223	                "[%s] body gap %d: idle=%ldms at=%ums bytes=%u\n",
1224	                TAG, i + 1, (long)progress_gap[i], (unsigned)progress_at[i],
1225	                (unsigned)progress_bytes[i]);
1226	        }
1227	    }
1228	
1229	    if (vela_http_body_unframed(chunked, content_length) && !eof) {
1230	        /* No length information: the wait can only end by the peer closing
1231	         * or by the socket timeout.  Name it, so an inflated body_ms on such
1232	         * a reply is not read as slow generation. */
1233	
1234	        syslog(LOG_WARNING,
1235	            "[%s] response has neither Content-Length nor chunked framing; "
1236	            "body end depends on the peer closing\n", TAG);
1237	    }
1238	
1239	    resp_buf[resp_pos] = '\0';
1240	    tls_raw_release(raw);
1241	
1242	    if (timing != NULL && first_byte_seen) {
1243	        /* Measured from the first byte, so headers and body form one span
1244	         * and never overlap ttfb_ms. */
1245	
1246	        timing->body_ms = agent_elapsed_ms(t0, agent_mono_ms())
1247	            - timing->ttfb_ms;
1248	        if (timing->body_ms < 0) {
1249	            timing->body_ms = AGENT_T_NA;
1250	        }
1251	    }
1252	
1253	
1254	    /* A body that filled the caller's buffer was cut off mid-stream.  The
1255	     * caller only sees a short string, so a JSON consumer reports a syntax
1256	     * error that does not exist in the server's reply.  Name the real cause
1257	     * here, where the capacity is still known. */
1258	    if (resp_pos >= resp_cap - 1) {
1259	        syslog(LOG_ERR, "[%s] response body truncated at %zu bytes "
1260	               "(buf cap %zu): reply larger than buffer\n",
1261	               TAG, resp_pos, resp_cap);
1262	    }
1263	
1264	    /* Chunked decode */
1265	    if (chunked) {
1266	        resp_pos = decode_chunked(resp_buf, resp_pos);
1267	        resp_buf[resp_pos] = '\0';
1268	    }
1269	
1270	    if (out_body_len)
1271	        *out_body_len = resp_pos;
1272	
1273	    return http_status;
1274	}
1275	
1276	/* ── Deadline-bounded streaming request ──────────────────────── */
1277	
1278	/* Every I/O below is one slice at a time.  The socket timeout is recomputed
1279	 * from the remaining budget before each slice, so a request cannot outlive
1280	 * its deadline even if the peer stops sending, and a cancel is noticed
1281	 * within VELA_REQ_IO_SLICE_MS rather than at the next phase boundary. */
1282	
1283	struct vela_emit {
1284	    const vela_resp_sink_t *sink;
1285	    char  *buf;
1286	    size_t cap;
1287	    size_t len;
1288	    bool   truncated;
1289	};
1290	
1291	static int emit_bytes(struct vela_emit *e, const char *data, size_t len)
1292	{
1293	    size_t room;
1294	    size_t copy;
1295	
1296	    if (len == 0) {
1297	        return 0;
1298	    }
1299	
1300	    if (e->sink != NULL) {
1301	        return e->sink->write(e->sink->ctx, data, len);
1302	    }
1303	
1304	    if (e->buf == NULL || e->cap == 0) {
1305	        e->truncated = true;
1306	        return 0;
1307	    }
1308	
1309	    room = e->cap - 1 - e->len;
1310	    copy = (len < room) ? len : room;
1311	
1312	    if (copy > 0) {
1313	        memcpy(e->buf + e->len, data, copy);
1314	        e->len += copy;
1315	        e->buf[e->len] = '\0';
1316	    }
1317	
1318	    if (copy < len) {
1319	        e->truncated = true;
1320	    }
1321	
1322	    return 0;
1323	}
1324	
1325	/* Incremental chunked decoder.  The whole body is never in one buffer, so
1326	 * vela_http_chunked_complete() cannot be used here: the state has to advance
1327	 * as bytes arrive.  A zero-size chunk ends the message; trailer fields after
1328	 * it are not consumed, which matches the framing rule used by the buffered
1329	 * reader. */
1330	
1331	enum vela_chunk_state {
1332	    VELA_CHUNK_SIZE = 0,
1333	    VELA_CHUNK_DATA,
1334	    VELA_CHUNK_DATA_END,
1335	    VELA_CHUNK_DONE
1336	};
1337	
1338	struct vela_chunk_dec {
1339	    enum vela_chunk_state state;
1340	    size_t remaining;
1341	    char   line[24];
1342	    size_t line_len;
1343	};
1344	
1345	static int chunk_feed(struct vela_chunk_dec *d, struct vela_emit *e,
1346	    const char *data, size_t len)
1347	{
1348	    size_t i = 0;
1349	
1350	    while (i < len && d->state != VELA_CHUNK_DONE) {
1351	        switch (d->state) {
1352	        case VELA_CHUNK_SIZE:
1353	            while (i < len) {
1354	                char c = data[i++];
1355	
1356	                if (c == '\n') {
1357	                    long sz;
1358	
1359	                    d->line[d->line_len] = '\0';
1360	                    sz = strtol(d->line, NULL, 16);
1361	                    d->line_len = 0;
1362	
1363	                    if (sz <= 0) {
1364	                        d->state = VELA_CHUNK_DONE;
1365	                    } else {
1366	                        d->remaining = (size_t)sz;
1367	                        d->state = VELA_CHUNK_DATA;
1368	                    }
1369	
1370	                    break;
1371	                }
1372	
1373	                if (c != '\r' && d->line_len + 1 < sizeof(d->line)) {
1374	                    d->line[d->line_len++] = c;
1375	                }
1376	            }
1377	            break;
1378	
1379	        case VELA_CHUNK_DATA:
1380	            {
1381	                size_t take = len - i;
1382	
1383	                if (take > d->remaining) {
1384	                    take = d->remaining;
1385	                }
1386	
1387	                int emit_rc = emit_bytes(e, data + i, take);
1388	                if (emit_rc < 0) {
1389	                    return -1;
1390	                }
1391	                if (emit_rc > 0) {
1392	                    d->state = VELA_CHUNK_DONE;
1393	                    return 1;
1394	                }
1395	
1396	                i += take;
1397	                d->remaining -= take;
1398	
1399	                if (d->remaining == 0) {
1400	                    d->state = VELA_CHUNK_DATA_END;
1401	                }
1402	            }
1403	            break;
1404	
1405	        case VELA_CHUNK_DATA_END:
1406	            while (i < len) {
1407	                char c = data[i++];
1408	
1409	                if (c == '\n') {
1410	                    d->state = VELA_CHUNK_SIZE;
1411	                    break;
1412	                }
1413	            }
1414	            break;
1415	
1416	        case VELA_CHUNK_DONE:
1417	            break;
1418	        }
1419	    }
1420	
1421	    return 0;
1422	}
1423	
1424	/* A read that only means "nothing yet" must not end the request. */
1425	
1426	static bool stream_read_retryable(int ret)
1427	{
1428	    return ret == MBEDTLS_ERR_SSL_WANT_READ
1429	        || ret == MBEDTLS_ERR_SSL_WANT_WRITE
1430	        || ret == MBEDTLS_ERR_SSL_TIMEOUT
1431	        || (ret == MBEDTLS_ERR_NET_RECV_FAILED
1432	            && (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR));
1433	}
1434	
1435	static void stream_set_timeout(tls_ctx_t *ctx, uint32_t ms)
1436	{
1437	    struct timeval tv;
1438	
1439	    if (ctx->net.fd < 0) {
1440	        return;
1441	    }
1442	
1443	    if (ms == 0) {
1444	        ms = 1;
1445	    }
1446	
1447	    tv.tv_sec = (time_t)(ms / 1000u);
1448	    tv.tv_usec = (suseconds_t)((ms % 1000u) * 1000u);
1449	
1450	    if (tv.tv_sec == 0 && tv.tv_usec == 0) {
1451	        tv.tv_usec = 1000;
1452	    }
1453	
1454	    setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
1455	    setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
1456	}
1457	
1458	static int stream_write_all(tls_ctx_t *ctx, const char *what,
1459	    const char *buf, size_t len, const vela_req_ctl_t *ctl)

1459	    const char *buf, size_t len, const vela_req_ctl_t *ctl)
1460	{
1461	    size_t off = 0;
1462	    uint32_t last_progress = agent_mono_ms();
1463	    int stalls = 0;
1464	
1465	    while (off < len) {
1466	        uint32_t now = agent_mono_ms();
1467	        size_t chunk;
1468	        int ret;
1469	
1470	        if (vela_req_cancelled(ctl)) {
1471	            return VELA_TLS_ERR_CANCELLED;
1472	        }
1473	
1474	        if (vela_req_budget_ms(ctl, now) == 0) {
1475	            return VELA_TLS_ERR_TIMEOUT;
1476	        }
1477	
1478	        /* No deadline and no progress: bound the wait anyway, so a stalled
1479	         * peer cannot hold the request thread forever. */
1480	
1481	        if (ctl == NULL || ctl->deadline_ms == 0) {
1482	            if (agent_elapsed_ms(last_progress, now) > 60000) {
1483	                syslog(LOG_ERR, "[%s] %s write stalled with no deadline\n",
1484	                    TAG, what);
1485	                return VELA_TLS_ERR_TIMEOUT;
1486	            }
1487	        }
1488	
1489	        stream_set_timeout(ctx, vela_req_io_timeout_ms(ctl, now,
1490	            VELA_REQ_IO_SLICE_MS));
1491	
1492	        chunk = len - off;
1493	        /* 受控流可使用完整 TLS 记录；原来的普通请求分片保持不变。 */
1494	        size_t limit = ctl != NULL ? 16384u : TLS_WRITE_CHUNK;
1495	        if (chunk > limit) chunk = limit;
1496	
1497	        ret = mbedtls_ssl_write(&ctx->ssl, (const unsigned char *)buf + off,
1498	            chunk);
1499	
1500	        if (ret > 0) {
1501	            off += (size_t)ret;
1502	            last_progress = agent_mono_ms();
1503	            stalls = 0;
1504	            continue;
1505	        }
1506	
1507	        if (ret == 0) {
1508	            return VELA_TLS_ERR_WRITE;
1509	        }
1510	
1511	        if (ret == MBEDTLS_ERR_SSL_WANT_WRITE
1512	            || ret == MBEDTLS_ERR_SSL_WANT_READ
1513	            || (ret == MBEDTLS_ERR_NET_SEND_FAILED
1514	                && (errno == EAGAIN || errno == EWOULDBLOCK ||
1515	                    errno == EINTR || errno == ENOMEM))
1516	            || ret == MBEDTLS_ERR_SSL_TIMEOUT) {
1517	            /* A full send buffer is retryable, but only for a bounded
1518	             * number of slices. */
1519	
1520	            int wait_rc = tls_wait_socket(ctx->net.fd,
1521	                ret == MBEDTLS_ERR_SSL_WANT_READ ? POLLIN : POLLOUT, ctl);
1522	            if (wait_rc != 0) {
1523	                return wait_rc;
1524	            }
1525	
1526	            /* A peer that went away leaves an error on the socket; the
1527	             * next write would only spin until the budget is gone. */
1528	
1529	            {
1530	                int soerr = 0;
1531	                socklen_t slen = sizeof(soerr);
1532	
1533	                if (getsockopt(ctx->net.fd, SOL_SOCKET, SO_ERROR, &soerr,
1534	                               &slen) == 0 && soerr != 0) {
1535	                    syslog(LOG_ERR,
1536	                        "[%s] %s write sees socket error %d at %u/%u\n",
1537	                        TAG, what, soerr, (unsigned)off, (unsigned)len);
1538	                    return VELA_TLS_ERR_WRITE;
1539	                }
1540	            }
1541	
1542	            if (++stalls > 120) {
1543	                syslog(LOG_ERR, "[%s] %s write gave up at %u/%u\n", TAG, what,
1544	                    (unsigned)off, (unsigned)len);
1545	                return VELA_TLS_ERR_WRITE;
1546	            }
1547	
1548	            continue;
1549	        }
1550	
1551	        syslog(LOG_ERR, "[%s] %s write failed ret=-0x%04x errno=%d at %u/%u\n", TAG,
1552	            what, -ret, errno, (unsigned)off, (unsigned)len);
1553	        return VELA_TLS_ERR_WRITE;
1554	    }
1555	
1556	    return 0;
1557	}
1558	
1559	/* 有界合并上传源的短片段，避免前缀、WAV 头和每个余片各发一条 TLS 记录。
1560	 * 缓冲放在堆上；不增加语音工作线程栈，也不延长原取消与截止预算。 */
1561	static int stream_send_body(tls_ctx_t *ctx, const vela_body_src_t *body,
1562	                            const vela_req_ctl_t *ctl)
1563	{
1564	    if (body == NULL || body->len == 0) return 0;
1565	    if (body->read == NULL) return VELA_TLS_ERR_READ;
1566	    const size_t capacity = ctl != NULL ? 16384u : 4096u;
1567	    char *piece = malloc(capacity);
1568	    if (!piece) return VELA_TLS_ERR_OVERFLOW;
1569	    size_t sent = 0;
1570	    int ret = 0;
1571	    while (sent < body->len) {
1572	        size_t target = body->len - sent;
1573	        if (target > capacity) target = capacity;
1574	        size_t used = 0;
1575	        while (used < target) {
1576	            if (vela_req_cancelled(ctl)) { ret = VELA_TLS_ERR_CANCELLED; goto out; }
1577	            if (vela_req_budget_ms(ctl, agent_mono_ms()) == 0) {
1578	                ret = VELA_TLS_ERR_TIMEOUT; goto out;
1579	            }
1580	            int got = body->read(body->ctx, piece + used, target - used);
1581	            if (got < 0) { ret = VELA_TLS_ERR_READ; goto out; }
1582	            if (got == 0) { ret = VELA_TLS_ERR_WRITE; goto out; }
1583	            if ((size_t)got > target - used) { ret = VELA_TLS_ERR_OVERFLOW; goto out; }
1584	            used += (size_t)got;
1585	        }
1586	        ret = stream_write_all(ctx, "body", piece, used, ctl);
1587	        if (ret != 0) goto out;
1588	        sent += used;
1589	    }
1590	out:
1591	    /* 上传片段可能包含录音或提示词，归还堆之前清零。 */
1592	    for (size_t i=0;i<capacity;i++) ((volatile unsigned char *)piece)[i]=0;
1593	    free(piece);
1594	    return ret;
1595	}
1596	
1597	int vela_https_request_stream(
1598	    const char *host,
1599	    const char *port,
1600	    const char *method,
1601	    const char *path,
1602	    const vela_header_t *headers,
1603	    const vela_body_src_t *body,
1604	    const vela_resp_sink_t *sink,
1605	    const vela_req_ctl_t *ctl,
1606	    char *resp_buf,
1607	    size_t resp_cap,
1608	    size_t *out_body_len,
1609	    int *out_status,
1610	    agent_llm_timing_t *timing)
1611	{
1612	    tls_ctx_t ctx;
1613	    struct vela_emit emit;
1614	    struct vela_chunk_dec chunk;
1615	    char *hdr = NULL;
1616	    char tmp[8192];
1617	    size_t hdr_len = 0;
1618	    size_t body_got = 0;
1619	    long content_length = -1;
1620	    bool chunked = false;
1621	    bool header_done = false;
1622	    bool eof = false;
1623	    bool complete = false;
1624	    uint32_t mark;
1625	    uint32_t last_progress;
1626	    int status = 0;
1627	    int ret = 0;
1628	    int n;
1629	
1630	    if (host == NULL || port == NULL || method == NULL || path == NULL) {
1631	        return VELA_TLS_ERR_CONNECT;
1632	    }
1633	
1634	    if (out_body_len != NULL) {
1635	        *out_body_len = 0;
1636	    }
1637	
1638	    if (out_status != NULL) {
1639	        *out_status = 0;
1640	    }
1641	
1642	    if (resp_buf != NULL && resp_cap > 0) {
1643	        resp_buf[0] = '\0';
1644	    }
1645	
1646	    memset(&ctx, 0, sizeof(ctx));
1647	    ctx.abort_on_close = ctl != NULL;
1648	    memset(&chunk, 0, sizeof(chunk));
1649	
1650	    emit.sink = sink;
1651	    emit.buf = resp_buf;
1652	    emit.cap = resp_cap;
1653	    emit.len = 0;
1654	    emit.truncated = false;
1655	
1656	    if (vela_req_cancelled(ctl)) {
1657	        return VELA_TLS_ERR_CANCELLED;
1658	    }
1659	
1660	    if (vela_req_budget_ms(ctl, agent_mono_ms()) == 0) {
1661	        return VELA_TLS_ERR_TIMEOUT;
1662	    }
1663	
1664	    mark = agent_mono_ms();
1665	    last_progress = mark;
1666	
1667	    ret = tls_ctx_connect(&ctx, host, port, timing, ctl);
1668	    if (ret != 0) {
1669	        tls_ctx_free(&ctx);
1670	        return ret;
1671	    }
1672	
1673	    mark = agent_mono_ms();
1674	
1675	    /* Request headers.  Content-Length comes from the source's declared
1676	     * length, so the body is written without ever being assembled. */
1677	
1678	    hdr = malloc(4096);
1679	    if (hdr == NULL) {
1680	        tls_ctx_free(&ctx);
1681	        return VELA_TLS_ERR_OVERFLOW;
1682	    }
1683	
1684	    {
1685	        int pos = 0;
1686	
1687	#define SHDR(fmt, ...)                                          \
1688	    do {                                                        \
1689	        pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
1690	        if (pos >= 4096) {                                      \
1691	            free(hdr);                                          \
1692	            tls_ctx_free(&ctx);                                 \
1693	            return VELA_TLS_ERR_OVERFLOW;                       \
1694	        }                                                       \
1695	    } while (0)
1696	
1697	        SHDR("%s %s HTTP/1.1\r\n", method, path);
1698	        SHDR("Host: %s\r\n", host);
1699	        SHDR("Connection: close\r\n");
1700	        SHDR("User-Agent: agent-vela/1.0\r\n");
1701	
1702	        if (body != NULL && body->len > 0) {
1703	            SHDR("Content-Length: %zu\r\n", body->len);
1704	        }
1705	
1706	        if (headers != NULL) {
1707	            for (const vela_header_t *h = headers; h->name != NULL; h++) {
1708	                SHDR("%s: %s\r\n", h->name, h->value);
1709	            }
1710	        }
1711	
1712	        SHDR("\r\n");
1713	#undef SHDR
1714	
1715	        ret = stream_write_all(&ctx, "hdr", hdr, (size_t)pos, ctl);
1716	    }
1717	
1718	    free(hdr);
1719	    hdr = NULL;
1720	
1721	    if (ret != 0) {
1722	        tls_ctx_free(&ctx);
1723	        return ret;
1724	    }
1725	
1726	    if (timing != NULL) {
1727	        timing->send_ms = agent_elapsed_ms(mark, agent_mono_ms());
1728	    }
1729	
1730	    ret = stream_send_body(&ctx, body, ctl);
1731	    if (ret != 0) {
1732	        tls_ctx_free(&ctx);
1733	        return ret;
1734	    }
1735	
1736	    /* Response headers. */
1737	
1738	    while (!header_done && hdr_len < sizeof(tmp) - 1) {
1739	        uint32_t now = agent_mono_ms();
1740	
1741	        if (vela_req_cancelled(ctl)) {
1742	            ret = VELA_TLS_ERR_CANCELLED;
1743	            goto out;
1744	        }
1745	
1746	        if (vela_req_budget_ms(ctl, now) == 0) {
1747	            ret = VELA_TLS_ERR_TIMEOUT;
1748	            goto out;
1749	        }
1750	
1751	        if ((ctl == NULL || ctl->deadline_ms == 0)
1752	            && agent_elapsed_ms(last_progress, now) > 60000) {
1753	            ret = VELA_TLS_ERR_TIMEOUT;
1754	            goto out;
1755	        }
1756	
1757	        stream_set_timeout(&ctx, vela_req_io_timeout_ms(ctl, now,
1758	            VELA_REQ_IO_SLICE_MS));
1759	
1760	        n = mbedtls_ssl_read(&ctx.ssl, (unsigned char *)tmp + hdr_len,
1761	            sizeof(tmp) - 1 - hdr_len);
1762	
1763	        if (n > 0) {
1764	            hdr_len += (size_t)n;
1765	            tmp[hdr_len] = '\0';
1766	            last_progress = agent_mono_ms();
1767	
1768	            if (memmem(tmp, hdr_len, "\r\n\r\n", 4) != NULL) {
1769	                header_done = true;
1770	            }
1771	
1772	            continue;
1773	        }
1774	
1775	        if (n == 0 || n == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1776	            eof = true;
1777	            break;
1778	        }
1779	
1780	        if (stream_read_retryable(n)) {
1781	            ret = tls_wait_socket(ctx.net.fd,
1782	                n == MBEDTLS_ERR_SSL_WANT_WRITE ? POLLOUT : POLLIN, ctl);
1783	            if (ret != 0) {
1784	                goto out;
1785	            }
1786	            continue;
1787	        }
1788	
1789	        syslog(LOG_ERR, "[%s] stream header read ret=-0x%04x\n", TAG, -n);
1790	        ret = VELA_TLS_ERR_READ;
1791	        goto out;
1792	    }
1793	
1794	    if (!header_done) {
1795	        ret = eof ? VELA_TLS_ERR_READ : VELA_TLS_ERR_OVERFLOW;
1796	        goto out;
1797	    }
1798	
1799	    if (sscanf(tmp, "HTTP/1.%*d %d", &status) != 1) {
1800	        syslog(LOG_ERR, "[%s] stream: bad status line: %.80s\n", TAG, tmp);
1801	        ret = VELA_TLS_ERR_READ;
1802	        goto out;
1803	    }
1804	
1805	    {
1806	        char *body_start = (char *)memmem(tmp, hdr_len, "\r\n\r\n", 4) + 4;
1807	        char *cl;
1808	        char *te;
1809	        size_t initial = hdr_len - (size_t)(body_start - tmp);
1810	
1811	        cl = strcasestr(tmp, "Content-Length:");
1812	        if (cl != NULL && cl < body_start) {
1813	            content_length = strtol(cl + strlen("Content-Length:"), NULL, 10);
1814	            if (content_length < 0 || content_length > 16 * 1024 * 1024) {
1815	                content_length = -1;
1816	            }
1817	        }
1818	
1819	        te = strcasestr(tmp, "Transfer-Encoding:");
1820	        if (te != NULL && te < body_start) {
1821	            chunked = (strcasestr(te, "chunked") != NULL);
1822	        }
1823	
1824	        if (initial > 0) {
1825	            if (chunked) {
1826	                int cf_rc = chunk_feed(&chunk, &emit, body_start, initial);
1827	                if (cf_rc < 0) {
1828	                    ret = VELA_TLS_ERR_SINK;
1829	                    goto out;
1830	                }
1831	                if (cf_rc > 0 || chunk.state == VELA_CHUNK_DONE) {
1832	                    complete = true;
1833	                }
1834	            } else {
1835	                size_t take = initial;
1836	
1837	                if (content_length >= 0 && (long)take > content_length) {
1838	                    take = (size_t)content_length;
1839	                }
1840	
1841	                int emit_rc = emit_bytes(&emit, body_start, take);
1842	                if (emit_rc < 0) {
1843	                    ret = VELA_TLS_ERR_SINK;
1844	                    goto out;
1845	                }
1846	                if (emit_rc > 0) {
1847	                    complete = true;
1848	                }
1849	
1850	                body_got = take;
1851	            }
1852	        }
1853	    }
1854	
1855	    /* Response body. */
1856	
1857	    for (;;) {
1858	        uint32_t now;
1859	
1860	        if (complete) {
1861	            break;
1862	        }
1863	
1864	        if (chunked) {
1865	            complete = (chunk.state == VELA_CHUNK_DONE);
1866	        } else if (content_length >= 0) {
1867	            complete = (body_got >= (size_t)content_length);
1868	        } else {
1869	            complete = eof;
1870	        }
1871	
1872	        if (complete) {
1873	            break;
1874	        }
1875	
1876	        now = agent_mono_ms();
1877	
1878	        if (vela_req_cancelled(ctl)) {
1879	            ret = VELA_TLS_ERR_CANCELLED;
1880	            goto out;
1881	        }
1882	
1883	        if (vela_req_budget_ms(ctl, now) == 0) {
1884	            ret = VELA_TLS_ERR_TIMEOUT;
1885	            goto out;
1886	        }
1887	
1888	        if ((ctl == NULL || ctl->deadline_ms == 0)
1889	            && agent_elapsed_ms(last_progress, now) > 60000) {
1890	            ret = VELA_TLS_ERR_TIMEOUT;
1891	            goto out;
1892	        }
1893	
1894	        stream_set_timeout(&ctx, vela_req_io_timeout_ms(ctl, now,
1895	            VELA_REQ_IO_SLICE_MS));
1896	
1897	        n = mbedtls_ssl_read(&ctx.ssl, (unsigned char *)tmp, sizeof(tmp));
1898	
1899	        if (n > 0) {
1900	            last_progress = agent_mono_ms();
1901	
1902	            if (chunked) {
1903	                int cf_rc = chunk_feed(&chunk, &emit, tmp, (size_t)n);
1904	                if (cf_rc < 0) {
1905	                    ret = VELA_TLS_ERR_SINK;
1906	                    goto out;
1907	                }
1908	                if (cf_rc > 0 || chunk.state == VELA_CHUNK_DONE) {
1909	                    break;
1910	                }
1911	            } else {
1912	                size_t take = (size_t)n;
1913	
1914	                if (content_length >= 0
1915	                    && body_got + take > (size_t)content_length) {
1916	                    take = (size_t)content_length - body_got;
1917	                }
1918	
1919	                int emit_rc = emit_bytes(&emit, tmp, take);
1920	                if (emit_rc < 0) {
1921	                    ret = VELA_TLS_ERR_SINK;
1922	                    goto out;
1923	                }
1924	                if (emit_rc > 0) {
1925	                    break;
1926	                }
1927	
1928	                body_got += take;
1929	            }
1930	
1931	            continue;
1932	        }
1933	
1934	        if (n == 0 || n == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
1935	            eof = true;
1936	
1937	            /* An unframed body ends at EOF; a framed one that ends early is
1938	             * truncated and must not be reported as complete. */
1939	
1940	            if (chunked && chunk.state != VELA_CHUNK_DONE) {
1941	                syslog(LOG_ERR, "[%s] chunked body ended before zero chunk\n",
1942	                    TAG);
1943	                ret = VELA_TLS_ERR_READ;
1944	                goto out;
1945	            }
1946	
1947	            if (content_length >= 0 && body_got < (size_t)content_length) {
1948	                syslog(LOG_ERR, "[%s] body ended at %u/%ld\n", TAG,
1949	                    (unsigned)body_got, content_length);
1950	                ret = VELA_TLS_ERR_READ;
1951	                goto out;
1952	            }
1953	
1954	            break;
1955	        }
1956	
1957	        if (stream_read_retryable(n)) {
1958	            ret = tls_wait_socket(ctx.net.fd,
1959	                n == MBEDTLS_ERR_SSL_WANT_WRITE ? POLLOUT : POLLIN, ctl);
1960	            if (ret != 0) {
1961	                goto out;
1962	            }
1963	            continue;
1964	        }
1965	
1966	        syslog(LOG_ERR, "[%s] stream body read ret=-0x%04x\n", TAG, -n);
1967	        ret = VELA_TLS_ERR_READ;
1968	        goto out;
1969	    }
1970	
1971	    if (timing != NULL) {
1972	        timing->ttfb_ms = AGENT_T_NA;
1973	        timing->body_ms = agent_elapsed_ms(mark, agent_mono_ms());
1974	    }
1975	
1976	    if (emit.truncated) {
1977	        syslog(LOG_ERR, "[%s] streamed response did not fit the %zu byte "
1978	            "buffer; caller must treat it as incomplete\n", TAG, resp_cap);
1979	    }
1980	
1981	    if (out_body_len != NULL) {
1982	        *out_body_len = (sink != NULL) ? body_got : emit.len;
1983	    }
1984	
1985	    if (out_status != NULL) {
1986	        *out_status = status;
1987	    }
1988	
1989	out:
1990	    ctx.abort_on_close = ctl != NULL && ret < 0;
1991	    /* Reclaim before returning, on every path.  A cancelled request must not
1992	     * leave a socket, a TLS context or a partially read record behind: the
1993	     * next request has to be able to start immediately. */
1994	
1995	    tls_ctx_free(&ctx);
1996	    return ret;
1997	}
