75	/* ── request body: prefix, base64 of a file, suffix ─────────────── */
76	
77	enum vc_src_state
78	{
79	  VC_SRC_PREFIX = 0,
80	  VC_SRC_HEADER,
81	  VC_SRC_BODY,
82	  VC_SRC_FLUSH,
83	  VC_SRC_SUFFIX,
84	  VC_SRC_DONE
85	};
86	
87	/* The request body carries one WAV file as base64.  The WAV header is
88	 * generated here and the samples come either from a file or from the
89	 * recording that is still in RAM, so an upload never needs a second copy
90	 * of the audio on the file system. */
91	
92	struct vc_body_src
93	{
94	  const char *prefix;
95	  const char *suffix;
96	  FILE       *f;                /* file source, or NULL */
97	  const uint8_t *mem;           /* memory source, or NULL */
98	  size_t     mem_len;
99	  size_t     mem_off;
100	  uint16_t   src_channels;      /* 1 or 2 */
101	  uint32_t   rate;
102	  uint32_t   out_samples;       /* mono samples in the uploaded WAV */
103	  struct vg_b64_stream b64;
104	  enum vc_src_state state;
105	  uint8_t in[VC_READ_CHUNK];
106	  uint8_t mono[VC_READ_CHUNK / 2];
107	  char    out[VC_B64_CHUNK];
108	  size_t  out_len;
109	  size_t  out_off;
110	  size_t  emitted;
111	};
112	
113	static int vc_src_fill(struct vc_body_src *s)
114	{
115	  s->out_len = 0;
116	  s->out_off = 0;
117	
118	  switch (s->state)
119	    {
120	      case VC_SRC_PREFIX:
121	        s->out_len = strlen(s->prefix);
122	        if (s->out_len > sizeof(s->out))
123	          {
124	            return -1;
125	          }
126	
127	        memcpy(s->out, s->prefix, s->out_len);
128	        s->state = VC_SRC_HEADER;
129	        break;
130	
131	      case VC_SRC_HEADER:
132	        {
133	          uint8_t hdr[VG_PCM_WAV_HDR];
134	          size_t n;
135	
136	          /* The uploaded file is always 16-bit mono, whatever the
137	           * recording format was. */
138	
139	          vg_pcm_wav_header_mono(hdr, s->rate, s->out_samples * 2u);
140	          n = vg_b64_stream_feed(&s->b64, hdr, sizeof(hdr), s->out,
141	                                 sizeof(s->out));
142	          s->state = VC_SRC_BODY;
143	          if (n == 0)
144	            {
145	              return vc_src_fill(s);
146	            }
147	
148	          s->out_len = n;
149	        }
150	        break;
151	
152	      case VC_SRC_BODY:
153	        {
154	          size_t got = 0;
155	
156	          if (s->mem != NULL)
157	            {
158	              size_t left = s->mem_len - s->mem_off;
159	
160	              got = (left > sizeof(s->in)) ? sizeof(s->in) : left;
161	              memcpy(s->in, s->mem + s->mem_off, got);
162	              s->mem_off += got;
163	            }
164	          else if (s->f != NULL)
165	            {
166	              got = fread(s->in, 1, sizeof(s->in), s->f);
167	            }
168	
169	          if (got == 0)
170	            {
171	              s->state = VC_SRC_FLUSH;
172	              return vc_src_fill(s);
173	            }
174	
175	          if (s->src_channels == 2)
176	            {
177	              /* Keep the first channel of every frame, so a stereo
178	               * recording is uploaded as the mono the service expects
179	               * without a second file. */
180	
181	              size_t frames = got / 4u;
182	              size_t i;
183	
184	              for (i = 0; i < frames; i++)
185	                {
186	                  s->mono[i * 2] = s->in[i * 4];
187	                  s->mono[i * 2 + 1] = s->in[i * 4 + 1];
188	                }
189	
190	              s->out_len = vg_b64_stream_feed(&s->b64, s->mono, frames * 2u,
191	                                              s->out, sizeof(s->out));
192	            }
193	          else
194	            {
195	              s->out_len = vg_b64_stream_feed(&s->b64, s->in, got, s->out,
196	                                              sizeof(s->out));
197	            }
198	
199	          if (s->out_len == 0)
200	            {
201	              /* Not an error: the encoder is carrying a partial group. */
202	
203	              return vc_src_fill(s);
204	            }
205	        }
206	        break;
207	
208	      case VC_SRC_FLUSH:
209	        s->out_len = vg_b64_stream_finish(&s->b64, s->out, sizeof(s->out));
210	        s->state = VC_SRC_SUFFIX;
211	
212	        if (s->out_len == 0)
213	          {
214	            return vc_src_fill(s);
215	          }
216	        break;
217	
218	      case VC_SRC_SUFFIX:
219	        s->out_len = strlen(s->suffix);
220	        if (s->out_len > sizeof(s->out))
221	          {
222	            return -1;
223	          }
224	
225	        memcpy(s->out, s->suffix, s->out_len);
226	        s->state = VC_SRC_DONE;
227	        break;
228	
229	      case VC_SRC_DONE:
230	      default:
231	        s->out_len = 0;
232	        return 0;
233	    }
234	
235	  return 1;
236	}
237	
238	static int vc_src_read(void *ctx, char *buf, size_t cap)
239	{
240	  struct vc_body_src *s = (struct vc_body_src *)ctx;
241	  size_t n;
242	
243	  while (s->out_off >= s->out_len)
244	    {
245	      int rc = vc_src_fill(s);
246	
247	      if (rc < 0)
248	        {
249	          return -1;
250	        }
251	
252	      if (rc == 0)
253	        {
254	          return 0;
255	        }
256	    }
257	
258	  n = s->out_len - s->out_off;
259	  if (n > cap)
260	    {
261	      n = cap;
262	    }
263	
264	  memcpy(buf, s->out + s->out_off, n);
265	  s->out_off += n;
266	  s->emitted += n;
267	  return (int)n;
268	}
