270	/* ── JSON helpers ───────────────────────────────────────────────── */
271	
272	static int vc_json_escape(const char *in, char *out, size_t cap)
273	{
274	  size_t o = 0;
275	
276	  if (in == NULL || out == NULL || cap == 0)
277	    {
278	      return -1;
279	    }
280	
281	  for (; *in != '\0'; in++)
282	    {
283	      unsigned char c = (unsigned char)*in;
284	
285	      if (c == '"' || c == '\\')
286	        {
287	          if (o + 2 >= cap)
288	            {
289	              return -1;
290	            }
291	
292	          out[o++] = '\\';
293	          out[o++] = (char)c;
294	        }
295	      else if (c == '\n' || c == '\r' || c == '\t')
296	        {
297	          if (o + 2 >= cap)
298	            {
299	              return -1;
300	            }
301	
302	          out[o++] = '\\';
303	          out[o++] = (c == '\n') ? 'n' : (c == '\r') ? 'r' : 't';
304	        }
305	      else if (c < 0x20)
306	        {
307	          if (o + 6 >= cap)
308	            {
309	              return -1;
310	            }
311	
312	          snprintf(out + o, cap - o, "\\u%04x", c);
313	          o += 6;
314	        }
315	      else
316	        {
317	          if (o + 1 >= cap)
318	            {
319	              return -1;
320	            }
321	
322	          out[o++] = (char)c;
323	        }
324	    }
325	
326	  out[o] = '\0';
327	  return (int)o;
328	}
