330	static const char *vc_extract_content(cJSON *root)
331	{
332	  cJSON *choices = cJSON_GetObjectItem(root, "choices");
333	  cJSON *first;
334	  cJSON *message;
335	  cJSON *content;
336	
337	  if (!cJSON_IsArray(choices))
338	    {
339	      return NULL;
340	    }
341	
342	  first = cJSON_GetArrayItem(choices, 0);
343	  if (first == NULL)
344	    {
345	      return NULL;
346	    }
347	
348	  message = cJSON_GetObjectItem(first, "message");
349	  if (message == NULL)
350	    {
351	      return NULL;
352	    }
353	
354	  content = cJSON_GetObjectItem(message, "content");
355	  if (!cJSON_IsString(content))
356	    {
357	      return NULL;
358	    }
359	
360	  return content->valuestring;
361	}
