418	                    const vela_resp_sink_t *sink, char *response, size_t cap,
419	                    size_t *bytes, int *status, const vela_req_ctl_t *ctl,
420	                    agent_llm_timing_t *timing)
421	{
422	#ifdef CONFIG_VG_VOICE_TEST_FIXTURE
