425	  memcpy(mode,g_fixture_mode,sizeof(mode));
426	  /* 只注入一次目标请求；TTS 重试回到真实服务，保留原文字。 */
427	  if (mode[0] && (!asr || !strncmp(mode,"asr",3))) g_fixture_mode[0] = 0;
428	  pthread_mutex_unlock(&g_fixture_lock);
