443	/* Post the prepared body and read the transcript out of the reply. */
444	static enum vg_vc_result vc_asr_post(struct vc_body_src *src, size_t body_len,
445	                                     const vela_req_ctl_t *ctl, char *text,
446	                                     size_t cap, struct vg_vc_info *info)
447	{
448	  char resp[VC_RESP_MAX];
449	  size_t body_out = 0;
450	  int status = 0;
451	  int ret;
452	  vela_body_src_t body;
453	
454	  body.len = body_len;
455	  body.read = vc_src_read;
456	  body.ctx = src;
457	
458	  {
459	    agent_llm_timing_t t;
460	    vc_timing_init(&t);
461	    ret = vc_post(true, NULL, &body, NULL, resp, sizeof(resp),
462	                                 &body_out, &status, ctl, &t);
463	    vc_timing_log("asr", &t);
464	  }
465	
466	  info->status = status;
467	  info->resp_bytes = (uint32_t)body_out;
468	  info->req_bytes = (uint32_t)body_len;
469	
470	  if (ret != 0)
471	    {
472	      enum vg_vc_result rc = vc_from_transport(ret);
473	
474	      syslog(LOG_ERR, "[%s] asr: transport failed: %d (%s)\n", TAG, ret,
475	             vg_vc_result_name(rc));
476	      return rc;
477	    }
478	
479	  if (status != 200)
480	    {
481	      syslog(LOG_ERR, "[%s] asr: http %d\n", TAG, status);
482	      return VG_VC_HTTP;
483	    }
484	
485	  {
486	    cJSON *root = cJSON_Parse(resp);
487	    const char *content;
488	
489	    if (root == NULL)
490	      {
491	        return VG_VC_FORMAT;
492	      }
493	
494	    content = vc_extract_content(root);
495	
496	    if (content == NULL)
497	      {
498	        cJSON_Delete(root);
499	        return VG_VC_FORMAT;
500	      }
501	
502	    if (content[0] == '\0')
503	      {
504	        cJSON_Delete(root);
505	        return VG_VC_EMPTY;
506	      }
507	
508	    if (strlen(content) >= cap)
509	      {
510	        /* A cut transcript could name a different point.  Refuse it
511	         * instead of sending a truncated question to the agent. */
512	
513	        cJSON_Delete(root);
514	        return VG_VC_FORMAT;
515	      }
516	
517	    snprintf(text, cap, "%s", content);
518	    cJSON_Delete(root);
519	  }
520	
521	  return VG_VC_OK;
522	}
