524	/* The elapsed time covers the whole recognition, file work included. */
525	static enum vg_vc_result vc_asr_done(enum vg_vc_result rc,
526	                                     struct vg_vc_info *info,
527	                                     const struct timespec *mono_start)
528	{
529	  struct timespec mono_end;
530	
531	  clock_gettime(CLOCK_MONOTONIC, &mono_end);
532	  info->elapsed_ms =
533	      (uint32_t)((mono_end.tv_sec - mono_start->tv_sec) * 1000
534	                 + (mono_end.tv_nsec - mono_start->tv_nsec) / 1000000);
535	  return rc;
536	}
