538	enum vg_vc_result vg_voice_cloud_asr(const char *clip_path,
539	                                     const vela_req_ctl_t *ctl,
540	                                     char *text, size_t cap,
541	                                     struct vg_vc_info *info)
542	{
543	  struct vg_pcm_wav wav;
544	  struct vc_body_src src;
545	  struct vg_vc_info local;
546	  struct timespec mono_start;
547	  size_t body_len;
548	  size_t b64_len;
549	  size_t upload_bytes;
550	  enum vg_vc_result rc;
551	
552	  if (info == NULL)
553	    {
554	      info = &local;
555	    }
556	
557	  memset(info, 0, sizeof(*info));
558	  clock_gettime(CLOCK_MONOTONIC, &mono_start);
559	
560	  if (text == NULL || cap == 0)
561	    {
562	      return VG_VC_IO;
563	    }
564	
565	  text[0] = '\0';
566	
567	  if (clip_path == NULL)
568	    {
569	      clip_path = VG_VC_CLIP_PATH;
570	    }
571	
572	  src.f = fopen(clip_path, "rb");
573	  if (src.f == NULL)
574	    {
575	      syslog(LOG_ERR, "[%s] asr: open clip failed errno=%d\n", TAG, errno);
576	      vg_voice_cloud_cleanup();
577	      return VG_VC_IO;
578	    }
579	
580	  int probe_rc = vg_pcm_wav_probe_stream(src.f, &wav);
581	  if (probe_rc != 0 || wav.bits != 16 ||
582	      wav.channels == 0 || wav.channels > 2 || wav.data_bytes == 0)
583	    {
584	      syslog(LOG_ERR, "[%s] asr: wav probe failed rc=%d bits=%u channels=%u\n",
585	             TAG, probe_rc, wav.bits, wav.channels);
586	      fclose(src.f);
587	      src.f = NULL;
588	      vg_voice_cloud_cleanup();
589	      return VG_VC_IO;
590	    }
591	
592	  /* A file that ends before its data chunk claims would make the request
593	   * shorter than the length it announces, and the server would wait for
594	   * bytes that never come. */
595	
596	  if (fseek(src.f, 0, SEEK_END) == 0)
597	    {
598	      long fsize = ftell(src.f);
599	      if (fsize > (long)wav.data_off)
600	        {
601	          size_t avail = (size_t)fsize - (size_t)wav.data_off;
602	          if (avail < wav.data_bytes)
603	            {
604	              wav.data_bytes = (uint32_t)avail;
605	            }
606	        }
607	    }
608	
609	  FILE *f = src.f;
610	  memset(&src, 0, sizeof(src));
611	  src.f = f;
612	  src.prefix = vc_asr_prefix;
613	  src.suffix = vc_asr_suffix;
614	  src.src_channels = wav.channels;
615	  src.rate = wav.rate;
616	  src.out_samples = wav.data_bytes / ((uint32_t)wav.channels * 2u);
617	
618	  if (fseek(src.f, (long)wav.data_off, SEEK_SET) != 0)
619	    {
620	      fclose(src.f);
621	      vg_voice_cloud_cleanup();
622	      return VG_VC_IO;
623	    }
624	
625	  upload_bytes = VG_PCM_WAV_HDR + (size_t)src.out_samples * 2u;
626	  b64_len = 4u * ((upload_bytes + 2u) / 3u);
627	  body_len = strlen(vc_asr_prefix) + b64_len + strlen(vc_asr_suffix);
628	
629	  src.state = VC_SRC_PREFIX;
630	
631	  rc = vc_asr_post(&src, body_len, ctl, text, cap, info);
632	
633	  fclose(src.f);
634	  src.f = NULL;
635	
636	  rc = vc_asr_done(rc, info, &mono_start);
637	
638	  /* The recording exists only for this recognition; neither the file nor
639	   * a mono copy is kept for a retry. */
640	
641	  vg_voice_cloud_cleanup();
642	  return rc;
643	}
