645	/* Recognise a recording that is still in RAM.  The board keeps the
646	 * captured samples until the next recording, so the upload needs neither
647	 * a WAV file nor a mono copy of it on the eMMC. */
648	enum vg_vc_result vg_voice_cloud_asr_buffer(const int16_t *mono,
649	                                            size_t mono_bytes,
650	                                            const vela_req_ctl_t *ctl,
651	                                            char *text, size_t cap,
652	                                            struct vg_vc_info *info)
653	{
654	  struct vc_body_src src;
655	  struct vg_vc_info local;
656	  struct timespec mono_start;
657	  size_t body_len;
658	  size_t b64_len;
659	  size_t upload_bytes;
660	  enum vg_vc_result rc;
661	
662	  if (info == NULL)
663	    {
664	      info = &local;
665	    }
666	
667	  memset(info, 0, sizeof(*info));
668	  clock_gettime(CLOCK_MONOTONIC, &mono_start);
669	
670	  if (text == NULL || cap == 0 || mono == NULL || mono_bytes < 2 ||
671	      mono_bytes > VG_VOICE_PCM_MAX_BYTES || (mono_bytes & 1u) != 0)
672	    {
673	      return VG_VC_IO;
674	    }
675	
676	  text[0] = '\0';
677	
678	  memset(&src, 0, sizeof(src));
679	  src.prefix = vc_asr_prefix;
680	  src.suffix = vc_asr_suffix;
681	  src.mem = (const uint8_t *)mono;
682	  src.mem_len = mono_bytes;
683	  src.src_channels = 1;
684	  src.rate = VG_VOICE_RATE_HZ;
685	  src.out_samples = (uint32_t)(mono_bytes / 2u);
686	  src.state = VC_SRC_PREFIX;
687	
688	  upload_bytes = VG_PCM_WAV_HDR + mono_bytes;
689	  b64_len = 4u * ((upload_bytes + 2u) / 3u);
690	  body_len = strlen(vc_asr_prefix) + b64_len + strlen(vc_asr_suffix);
691	
692	  rc = vc_asr_post(&src, body_len, ctl, text, cap, info);
693	  rc = vc_asr_done(rc, info, &mono_start);
694	  return rc;
695	}
