697	/* ── TTS ────────────────────────────────────────────────────────── */
698	
699	/* The synthesised samples are kept in RAM until the reply is complete
700	 * and are then resampled into the WAV the player takes.  An answer is a
701	 * few seconds of speech, so the buffer stays far below the limit below,
702	 * and no intermediate file is written to the eMMC. */
703	#define VC_PCM_MAX_BYTES (512u * 1024u)
704	
705	struct vc_tts_sink
706	{
707	  uint8_t *pcm;
708	  size_t   pcm_len;
709	  size_t   pcm_cap;
710	  char  *line;
711	  size_t line_len;
712	  size_t line_cap;
713	  char  *payload;
714	  size_t pcm_bytes;
715	  bool   done;
716	  int    error;
717	};
718	
719	static int vc_tts_pcm_reserve(struct vc_tts_sink *s, size_t extra)
720	{
721	  size_t need = s->pcm_len + extra;
722	  size_t ncap;
723	  uint8_t *buf;
724	
725	  if (need <= s->pcm_cap)
726	    {
727	      return 0;
728	    }
729	
730	  if (need > VC_PCM_MAX_BYTES)
731	    {
732	      syslog(LOG_ERR, "[%s] tts: reply over %u bytes\n", TAG,
733	             (unsigned)VC_PCM_MAX_BYTES);
734	      return -1;
735	    }
736	
737	  ncap = (s->pcm_cap == 0) ? 32768 : s->pcm_cap * 2;
738	  while (ncap < need)
739	    {
740	      ncap *= 2;
741	    }
742	
743	  if (ncap > VC_PCM_MAX_BYTES)
744	    {
745	      ncap = VC_PCM_MAX_BYTES;
746	    }
747	
748	  buf = realloc(s->pcm, ncap);
749	  if (buf == NULL)
750	    {
751	      return -1;
752	    }
753	
754	  s->pcm = buf;
755	  s->pcm_cap = ncap;
756	  return 0;
757	}
758	
759	static int vc_tts_emit_pcm(struct vc_tts_sink *s, const char *b64, size_t len)
760	{
761	  uint8_t pcm[VC_PCM_CHUNK];
762	  const size_t step = (sizeof(pcm) / 3) * 4;  /* whole base64 groups */
763	  size_t off = 0;
764	
765	  /* The service chooses the chunk size, and a real answer arrived as one
766	   * 40 KB base64 string.  Decode in pieces that fit the buffer instead of
767	   * assuming a chunk size. */
768	
769	  while (off < len)
770	    {
771	      size_t take = len - off;
772	      int n;
773	
774	      if (take > step)
775	        {
776	          take = step;
777	        }
778	
779	      n = vg_b64_decode(b64 + off, take, pcm, sizeof(pcm));
780	      if (n < 0)
781	        {
782	          syslog(LOG_ERR, "[%s] tts: bad base64 chunk of %u bytes\n", TAG,
783	                 (unsigned)take);
784	          return -1;
785	        }
786	
787	      if (n > 0)
788	        {
789	          if (vc_tts_pcm_reserve(s, (size_t)n) != 0)
790	            {
791	              return -1;
792	            }
793	
794	          memcpy(s->pcm + s->pcm_len, pcm, (size_t)n);
795	          s->pcm_len += (size_t)n;
796	        }
797	
798	      s->pcm_bytes += (size_t)n;
799	      off += take;
800	    }
801	
802	  return 0;
803	}
804	
805	static int vc_tts_grow(struct vc_tts_sink *s)
806	{
807	  size_t ncap = (s->line_cap == 0) ? VC_SSE_LINE_INIT : s->line_cap * 2;
808	  char *line;
809	  char *payload;
810	
811	  if (ncap > VC_SSE_LINE_MAX)
812	    {
813	      return -1;
814	    }
815	
816	  line = realloc(s->line, ncap);
817	  if (line == NULL)
818	    {
819	      return -1;
820	    }
821	
822	  payload = realloc(s->payload, ncap);
823	  if (payload == NULL)
824	    {
825	      s->line = line;
826	      return -1;
827	    }
828	
829	  s->line = line;
830	  s->payload = payload;
831	  s->line_cap = ncap;
832	  return 0;
833	}
834	
835	static int vc_tts_line(struct vc_tts_sink *s)
836	{
837	  int rc;
838	
839	  if (s->line_len == 0)
840	    {
841	      return 0;
842	    }
843	
844	  s->line[s->line_len] = '\0';
845	
846	  rc = vg_sse_line_data(s->line, s->line_len, s->payload, s->line_cap);
847	  s->line_len = 0;
848	
849	  if (rc == -1)
850	    {
851	      s->done = true;
852	      return 0;
853	    }
854	
855	  if (rc <= 0)
856	    {
857	      return (rc == -2) ? -1 : 0;
858	    }
859	
860	  {
861	    cJSON *root = cJSON_Parse(s->payload);
862	    cJSON *choices;
863	    cJSON *first;
864	    cJSON *delta;
865	    cJSON *audio;
866	    cJSON *data;
867	
868	    if (root == NULL)
869	      {
870	        return -1;
871	      }
872	
873	    choices = cJSON_GetObjectItem(root, "choices");
874	    first = cJSON_IsArray(choices) ? cJSON_GetArrayItem(choices, 0) : NULL;
875	    delta = (first != NULL) ? cJSON_GetObjectItem(first, "delta") : NULL;
876	    audio = (delta != NULL) ? cJSON_GetObjectItem(delta, "audio") : NULL;
877	    data = (audio != NULL) ? cJSON_GetObjectItem(audio, "data") : NULL;
878	    cJSON *finish = first ? cJSON_GetObjectItem(first, "finish_reason") : NULL;
879	    if (cJSON_IsString(finish) && strcmp(finish->valuestring, "stop") == 0)
880	      s->done = true;
881	
882	    if (cJSON_IsString(data) && data->valuestring != NULL)
883	      {
884	        rc = vc_tts_emit_pcm(s, data->valuestring,
885	                             strlen(data->valuestring));
886	        cJSON_Delete(root);
887	        return rc;
888	      }
889	
890	    cJSON_Delete(root);
891	  }
892	
893	  return 0;
894	}
895	
896	static int vc_tts_write(void *ctx, const char *data, size_t len)
897	{
898	  struct vc_tts_sink *s = (struct vc_tts_sink *)ctx;
899	  size_t i;
900	
901	  for (i = 0; i < len; i++)
902	    {
903	      if (s->error != 0)
904	        {
905	          return -1;
906	        }
907	
908	      if (data[i] == '\n')
909	        {
910	          if (vc_tts_line(s) < 0)
911	            {
912	              s->error = -1;
913	              return -1;
914	            }
915	
916	          if (s->done)
917	            {
918	              return 1;
919	            }
920	
921	          continue;
922	        }
923	
924	      if (s->line_len + 1 >= s->line_cap && vc_tts_grow(s) < 0)
925	        {
926	          /* A line this long is not a data line we understand; stopping is
927	           * better than silently dropping audio. */
928	
929	          syslog(LOG_ERR, "[%s] tts: SSE line over %u bytes\n", TAG,
930	                 (unsigned)s->line_cap);
931	          s->error = -1;
932	          return -1;
933	        }
934	
935	      s->line[s->line_len++] = data[i];
936	    }
937	
938	  return s->done ? 1 : 0;
939	}
940	
941	enum vg_vc_result vg_voice_cloud_tts(const char *text, const char *wav_out,
942	                                     const vela_req_ctl_t *ctl,
943	                                     struct vg_vc_info *info)
944	{
945	  struct vg_vc_info local;
946	  struct vc_tts_sink sink;
947	  char escaped[VG_VC_TEXT_MAX * 2];
948	  char *body = NULL;
949	  char resp[VC_RESP_MAX];
950	  const char *out_path = (wav_out != NULL) ? wav_out : VG_VC_TTS_WAV_PATH;
951	  size_t body_cap;
952	  size_t body_out = 0;
953	  int status = 0;
954	  int ret;
955	  enum vg_vc_result rc = VG_VC_OK;
956	  struct timespec mono_start;
957	  struct timespec mono_end;
958	
959	  if (info == NULL)
960	    {
961	      info = &local;
962	    }
963	
964	  memset(info, 0, sizeof(*info));
965	
966	  clock_gettime(CLOCK_MONOTONIC, &mono_start);
967	
968	  if (text == NULL || text[0] == '\0')
969	    {
970	      return VG_VC_NO_TEXT;
971	    }
972	
973	  if (vc_json_escape(text, escaped, sizeof(escaped)) < 0)
974	    {
975	      return VG_VC_FORMAT;
976	    }
977	
978	  body_cap = strlen(escaped) + 256;
979	  body = malloc(body_cap);
980	  if (body == NULL)
981	    {
982	      return VG_VC_IO;
983	    }
984	
985	  snprintf(body, body_cap,
986	           "{\"model\":\"" CONFIG_VG_VOICE_TTS_MODEL "\","
987	           "\"messages\":[{\"role\":\"assistant\",\"content\":\"%s\"}],"
988	           "\"audio\":{\"format\":\"pcm16\",\"voice\":\""
989	           CONFIG_VG_VOICE_TTS_VOICE "\"},\"stream\":true}",
990	           escaped);
991	
992	  memset(&sink, 0, sizeof(sink));
993	  if (vc_tts_grow(&sink) < 0)
994	    {
995	      free(body);
996	      return VG_VC_IO;
997	    }
998	
999	  {
1000	    vela_resp_sink_t rs;
1001	    agent_llm_timing_t t;
1002	
1003	    rs.write = vc_tts_write;
1004	    rs.ctx = &sink;
1005	
1006	    vc_timing_init(&t);
1007	    ret = vc_post(false, body, NULL, &rs, resp, sizeof(resp),
1008	                               &body_out, &status, ctl, &t);
1009	    vc_timing_log("tts", &t);
1010	  }
1011	
1012	  info->status = status;
1013	  info->resp_bytes = (uint32_t)body_out;
1014	  info->req_bytes = (uint32_t)strlen(body);
1015	
1016	  info->audio_bytes = (uint32_t)sink.pcm_bytes;
1017	
1018	  if (ret != 0 || sink.error != 0)
1019	    {
1020	      struct timespec now;
1021	      clock_gettime(CLOCK_MONOTONIC, &now);
1022	      uint32_t ms = (uint32_t)((uint64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000);
1023	      if (agent_http_cancelled(ctl)) rc = VG_VC_CANCELLED;
1024	      else if (ret == AGENT_HTTP_ERR_TIMEOUT || agent_http_stop(ctl, ms)) rc = VG_VC_TIMEOUT;
1025	      else if (sink.error != 0) rc = VG_VC_FORMAT;
1026	      else rc = (ret != 0) ? vc_from_transport(ret) : VG_VC_FORMAT;
1027	      goto out;
1028	    }
1029	
1030	  if (status != 200)
1031	    {
1032	      rc = VG_VC_HTTP;
1033	      goto out;
1034	    }
1035	
1036	  if (sink.pcm_bytes == 0 || (sink.pcm_bytes & 1u) ||
1037	      sink.line_len != 0 || !sink.done)
1038	    {
1039	      rc = VG_VC_FORMAT;
1040	      goto out;
1041	    }
1042	
1043	  /* Convert 24 kHz mono to the 16 kHz stereo the player was verified
1044	   * with.  The samples are already in RAM, so this is one pass into the
1045	   * WAV file and no intermediate file is involved. */
1046	
1047	  {
1048	    int16_t *pcm_in;
1049	    int16_t *pcm_out;
1050	    size_t samples = sink.pcm_len / 2;
1051	    size_t done = 0;
1052	    size_t out_total = (samples / 3u) * 2u;
1053	    struct vg_pcm_writer w;
1054	
1055	    if (samples == 0)
1056	      {
1057	        rc = VG_VC_IO;
1058	        goto out;
1059	      }
1060	
1061	    pcm_in = malloc(VC_PCM_SAMPLES * sizeof(int16_t));
1062	    pcm_out = malloc((VC_PCM_SAMPLES * 2u) * sizeof(int16_t));
1063	
1064	    if (pcm_in == NULL || pcm_out == NULL)
1065	      {
1066	        free(pcm_in);
1067	        free(pcm_out);
1068	        rc = VG_VC_IO;
1069	        goto out;
1070	      }
1071	
1072	    if (vg_pcm_writer_open(&w, out_path, out_total) != 0)
1073	      {
1074	        free(pcm_in);
1075	        free(pcm_out);
1076	        rc = VG_VC_IO;
1077	        goto out;
1078	      }
1079	
1080	    while (done < samples)
1081	      {
1082	        struct timespec now;
1083	        clock_gettime(CLOCK_MONOTONIC, &now);
1084	        uint32_t now_ms = (uint32_t)((uint64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000);
1085	        if (agent_http_stop(ctl, now_ms))
1086	          {
1087	            rc = agent_http_cancelled(ctl) ? VG_VC_CANCELLED : VG_VC_TIMEOUT;
1088	            break;
1089	          }
1090	        size_t batch = samples - done;
1091	        size_t got;
1092	        int out_n;
1093	
1094	        /* 15360 is a multiple of 3, so the 3:2 resampler never drops a
1095	         * partial group in the middle of the signal. */
1096	
1097	        if (batch > VC_PCM_SAMPLES)
1098	          {
1099	            batch = VC_PCM_SAMPLES;
1100	          }
1101	
1102	        memcpy(pcm_in, sink.pcm + done * 2, batch * 2);
1103	        got = batch;
1104	
1105	        out_n = vg_pcm_resample_24k_16k(pcm_in, got, pcm_out,
1106	                                        VC_PCM_SAMPLES * 2u);
1107	        if (out_n < 0 || vg_pcm_writer_write(&w, pcm_out,
1108	                                             (size_t)out_n) != 0)
1109	          {
1110	            break;
1111	          }
1112	
1113	        done += got;
1114	      }
1115	
1116	    /* Close unconditionally: the writer holds the output FILE, and a short
1117	     * read above would otherwise leave it open. */
1118	
1119	    {
1120	      int close_ret = vg_pcm_writer_close(&w);
1121	
1122	      if (done != samples || close_ret != 0)
1123	        {
1124	          free(pcm_in);
1125	          free(pcm_out);
1126	          if (rc == VG_VC_OK) rc = VG_VC_IO;
1127	          goto out;
1128	        }
1129	    }
1130	
1131	    free(pcm_in);
1132	    free(pcm_out);
1133	  }
1134	
1135	  clock_gettime(CLOCK_MONOTONIC, &mono_end);
1136	  info->elapsed_ms =
1137	      (uint32_t)((mono_end.tv_sec - mono_start.tv_sec) * 1000
1138	                 + (mono_end.tv_nsec - mono_start.tv_nsec) / 1000000);
1139	  uint32_t final_ms = (uint32_t)((uint64_t)mono_end.tv_sec * 1000 + mono_end.tv_nsec / 1000000);
1140	  rc = agent_http_stop(ctl, final_ms)
1141	      ? (agent_http_cancelled(ctl) ? VG_VC_CANCELLED : VG_VC_TIMEOUT)
1142	      : VG_VC_OK;
1143	
1144	out:
1145	  clock_gettime(CLOCK_MONOTONIC, &mono_end);
1146	  info->elapsed_ms =
1147	      (uint32_t)((mono_end.tv_sec - mono_start.tv_sec) * 1000
1148	                 + (mono_end.tv_nsec - mono_start.tv_nsec) / 1000000);
1149	
1150	  unlink(VG_VC_TTS_PCM_PATH);
1151	
1152	  if (rc != VG_VC_OK)
1153	    {
1154	      unlink(out_path);
1155	    }
1156	
1157	  free(sink.line);
1158	  free(sink.payload);
1159	  free(sink.pcm);
1160	  free(body);
1161	  return rc;
1162	}
