1164	void vg_voice_cloud_cleanup(void)
1165	{
1166	  unlink(VG_VC_CLIP_PATH);
1167	  unlink(VG_VC_CLIP_MONO_PATH);
1168	  unlink(VG_VC_TTS_PCM_PATH);
1169	}
