50	/* The worker owns the whole call chain: a 4 KB response buffer, the 4 KB body
51	 * piece and the 2 KB TLS read buffer inside the transport, the TLS handshake,
52	 * and the render buffers.  16 KB was not enough headroom for that stack. */
53	
54	/* mbedTLS handshake plus the ASR body builder measured around 10 KB of frame
55	 * at the fault site, but the handshake's deepest path is not observable from
56	 * the dump; 48 KB leaves room for the certificate parse. */
57	#define VR_STACK_SIZE   49152
58	#define VR_PRIORITY     118
59	#define VR_TICK_MS      50
60	#define VR_AGENT_POLL_MS 10
61	#define VR_PLAY_EXTRA_MS 5000u
