63	struct voice_round
64	{
65	  bool                 started;
66	  pthread_t            thread;
67	  sem_t                wake;
68	  struct vg_voice_session s;
69	  volatile int         cancel;
70	  volatile bool        press_pending;
71	  volatile bool        submit_pending;
72	  volatile bool        end_pending;
73	  volatile bool        retry_pending;
74	  volatile bool        hold_pending;
75	  volatile bool        hold_value;
76	  volatile bool        mute_pending;
77	  volatile bool        mute_value;
78	  volatile bool        quit;
79	  uint32_t             record_generation;
80	  uint32_t             clip_generation;
81	  uint32_t             asr_requests;
82	  uint32_t             tts_requests;
83	  uint32_t             end_requested_ms;
84	  char                 asr_src[80];
85	  bool                 muted;
86	  bool                 hold;
87	
88	  pthread_mutex_t      ui_lock;
89	  struct vg_voice_ui   ui;
90	};
91	
92	static struct voice_round g_vr;
93	static pthread_mutex_t g_start_lock = PTHREAD_MUTEX_INITIALIZER;
94	static bool g_round_ready;
95	
96	static uint32_t vr_now_ms(void)
97	{
98	  struct timespec ts;
99	
100	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
101	    {
102	      return 0;
103	    }
104	
105	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
106	                    + (uint64_t)ts.tv_nsec / 1000000u);
107	}
108	
109	/* Stage timing for the round.  The numbers are relative to the release
110	 * that started the budget, so the gaps between the stages show up in the
111	 * serial log instead of only in the total. */
112	
113	static uint32_t vr_elapsed_ms(void)
114	{
115	  uint32_t now = vr_now_ms();
116	
117	  if (g_vr.s.submit_ms == 0 || now < g_vr.s.submit_ms)
118	    {
119	      return 0;
120	    }
121	
122	  return now - g_vr.s.submit_ms;
123	}
124	
125	static void vr_log_stage(const char *stage)
126	{
127	  syslog(LOG_INFO, "[vgvoice] stage=%s t=%u\n", stage,
128	         (unsigned)vr_elapsed_ms());
129	}
