131	/* ── UI snapshot ────────────────────────────────────────────────── */
132	
133	static void vr_ui_set_status(const char *status)
134	{
135	  pthread_mutex_lock(&g_vr.ui_lock);
136	  snprintf(g_vr.ui.status, sizeof(g_vr.ui.status), "%s",
137	           status != NULL ? status : "");
138	  pthread_mutex_unlock(&g_vr.ui_lock);
139	}
140	
141	static void vr_ui_publish(void)
142	{
143	  struct vg_voice_session *s = &g_vr.s;
144	  uint32_t now = vr_now_ms();
145	
146	  pthread_mutex_lock(&g_vr.ui_lock);
147	  g_vr.ui.generation = s->generation;
148	  g_vr.ui.state = (uint32_t)s->state;
149	  g_vr.ui.muted = s->muted;
150	  g_vr.ui.speech_failed = s->speech_failed;
151	  g_vr.ui.record_left_ms =
152	      (s->state == VG_VS_RECORDING)
153	          ? (uint32_t)(VG_VS_RECORD_MAX_MS -
154	                       (now - s->record_ms > VG_VS_RECORD_MAX_MS
155	                            ? VG_VS_RECORD_MAX_MS
156	                            : now - s->record_ms))
157	          : 0;
158	  g_vr.ui.budget_left_ms = vg_vs_remaining_ms(s, now);
159	  g_vr.ui.result_left_ms = vg_vs_result_left_s(s, now) * 1000u;
160	  g_vr.ui.visible = (s->state != VG_VS_IDLE);
161	  snprintf(g_vr.ui.question, sizeof(g_vr.ui.question), "%s", s->text);
162	  /* s->answer holds the spoken summary; the overlay keeps the full display
163	   * text that was rendered from the same snapshot.  Only fall back to the
164	   * summary when no display text has been produced yet. */
165	
166	  if (!s->have_answer)
167	    {
168	      g_vr.ui.answer[0] = '\0';
169	    }
170	  else if (g_vr.ui.answer[0] == '\0')
171	    {
172	      snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", s->answer);
173	    }
174	  pthread_mutex_unlock(&g_vr.ui_lock);
175	}
