193	/* ── button callback ────────────────────────────────────────────── */
194	
195	/* Runs in the button task.  Nothing here may block: the pipeline stages poll
196	 * the cancel flag, and the worker reads the pending event. */
197	
198	static void vr_button(const struct vg_ptt_event_record *rec, void *arg)
199	{
200	  (void)arg;
201	
202	  if (rec->type == VG_PTT_EV_BEGIN)
203	    {
204	      g_vr.asr_src[0] = '\0';
205	      g_vr.cancel = 1;
206	      g_vr.press_pending = true;
207	      sem_post(&g_vr.wake);
208	    }
209	  else if (rec->type == VG_PTT_EV_SUBMIT)
210	    {
211	      g_vr.submit_pending = true;
212	      sem_post(&g_vr.wake);
213	    }
214	}
