216	/* ── stages ─────────────────────────────────────────────────────── */
217	
218	/* Wait for the recorder to close the WAV.  Bounded: a stuck audio task must
219	 * not hold the whole round. */
220	
221	static bool vr_wait_voice_idle(uint32_t limit_ms)
222	{
223	  return vg_voice_wait_idle(limit_ms);
224	}
225	
226	/* Recognise the recording.  Returns true and fills text on success. */
227	
228	static bool vr_stage_asr(char *text, size_t cap)
229	{
230	  struct vg_vc_info info;
231	  enum vg_vc_result rc;
232	  vela_req_ctl_t ctl;
233	
234	  ctl.deadline_ms = g_vr.s.deadline_ms;
235	  ctl.cancel = &g_vr.cancel;
236	
237	  while (vg_agent_round_voice_reserve() != 0)
238	    {
239	      if (g_vr.cancel) return false;
240	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
241	        { vr_ui_error("等待查询超时，请重试"); return false; }
242	      usleep(20000);
243	    }
244	
245	  vr_ui_set_status("识别中");
246	  vr_ui_publish();
247	  vr_log_stage("asr_begin");
248	
249	  __atomic_fetch_add(&g_vr.asr_requests, 1, __ATOMIC_RELAXED);
250	
251	  /* The recording is still in RAM: upload it from there.  A file is only
252	   * read when a caller named one, which is the diagnostic path. */
253	
254	  {
255	    size_t bytes = 0;
256	    int16_t *pcm = NULL;
257	    if (g_vr.asr_src[0] != '\0')
258	      {
259	        (void)vg_voice_finish_owned(g_vr.clip_generation, true);
260	        rc = vg_voice_cloud_asr(g_vr.asr_src, &ctl, text, cap, &info);
261	      }
262	    else if (vg_voice_clip_take_owned(g_vr.clip_generation, &pcm, &bytes) == 0)
263	      {
264	        rc = vg_voice_cloud_asr_buffer(pcm, bytes, &ctl, text, cap, &info);
265	        /* Volatile stores keep raw-audio cleanup before free observable. */
266	        volatile unsigned char *wipe = (volatile unsigned char *)pcm;
267	        for (size_t i = 0; i < bytes; i++) wipe[i] = 0;
268	        free(pcm);
269	      }
270	    else
271	      {
272	        memset(&info, 0, sizeof(info));
273	        rc = VG_VC_IO;
274	      }
275	  }
276	
277	  syslog(LOG_INFO, "[vgvoice] asr rc=%s status=%d req=%u resp=%u ms=%u\n",
278	         vg_vc_result_name(rc), info.status, (unsigned)info.req_bytes,
279	         (unsigned)info.resp_bytes, (unsigned)info.elapsed_ms);
280	  vr_log_stage("asr_end");
281	
282	  if (rc == VG_VC_CANCELLED)
283	    {
284	      return false;
285	    }
286	
287	  if (rc != VG_VC_OK)
288	    {
289	      if (rc == VG_VC_EMPTY)
290	        {
291	          vr_ui_error("没有听清，请再说一次");
292	        }
293	      else if (rc == VG_VC_TIMEOUT)
294	        {
295	          vr_ui_error("识别超时，请重试");
296	        }
297	      else if (rc == VG_VC_HTTP)
298	        {
299	          vr_ui_error("识别服务返回错误，请重试");
300	        }
301	      else
302	        {
303	          vr_ui_error("识别失败，请重试");
304	        }
305	
306	      return false;
307	    }
308	
309	  return true;
310	}
311	
312	/* Ask the on-board agent.  Returns true when the round finished inside the
313	 * budget and the answer is in display/speech. */
314	
315	static bool vr_wait_agent(uint32_t deadline_ms)
316	{
317	  for (;;)
318	    {
319	      enum vg_agent_round_state st;
320	
321	      /* Drive the channel here as well.  The HMI worker ticks every 100 ms,
322	       * but it can be busy with a report or advice write; a question that
323	       * sits QUEUED past the budget is indistinguishable from a model
324	       * timeout.  The submission guard keeps the two tickers from pushing
325	       * the same request twice. */
326	
327	      vg_agent_round_tick();
328	
329	      if (g_vr.cancel)
330	        {
331	          return false;
332	        }
333	
334	      st = vg_agent_round_state();
335	
336	      if (st == VG_AGENT_ROUND_DONE)
337	        {
338	          return true;
339	        }
340	
341	      if (st == VG_AGENT_ROUND_ERROR)
342	        {
343	          return false;
344	        }
345	
346	      if ((int32_t)(deadline_ms - vr_now_ms()) <= 0)
347	        {
348	          return false;
349	        }
350	
351	      usleep(VR_AGENT_POLL_MS * 1000);
352	    }
353	}
354	
355	/* Build the question and the deterministic answer for one recognised text.
356	 * Returns false with a user-facing reason when the request cannot be
357	 * answered inside the three-intent contract. */
358	
359	static bool vr_build_question(const char *text, char *question, size_t qcap,
360	                              char *tool, size_t tcap,
361	                              char *tool_json, size_t jcap,
362	                              char *target_id, size_t icap,
363	                              char *reason, size_t rcap)
364	{
365	  struct vg_voice_intent_result intent;
366	  struct vg_agent_point points[VG_AGENT_QUERY_MAX];
367	  struct vg_agent_query_result res;
368	  char token[VG_AGENT_QUERY_STR_MAX];
369	  const char *point_id;
370	  int n = 0;
371	  int rc;
372	
373	  if (target_id && icap > 0)
374	    {
375	      target_id[0] = '\0';
376	    }
377	
378	  if (vg_vi_classify(text, &intent) == VG_VI_REFUSED)
379	    {
380	      snprintf(reason, rcap, "语音只能查询当前异常、点位读数和告警恢复");
381	      return false;
382	    }
383	
384	  if (intent.intent == VG_VI_UNKNOWN)
385	    {
386	      snprintf(reason, rcap, "没有听清要查什么，请再说一次");
387	      return false;
388	    }
389	
390	  if (intent.intent == VG_VI_ANOMALY)
391	    {
392	      snprintf(question, qcap,
393	               "现在有哪些异常？请调用 vg_anomaly_read 获取完整列表，"
394	               "然后简要说明。");
395	      snprintf(tool, tcap, "vg_anomaly_read");
396	      snprintf(tool_json, jcap, "{}");
397	      return true;
398	    }
399	
400	  rc = vg_agent_tools_collect(points, VG_AGENT_QUERY_MAX, &n);
401	  if (rc != VG_AGENT_QUERY_OK && rc != VG_AGENT_QUERY_NO_SAMPLE)
402	    {
403	      snprintf(reason, rcap, "已确认点表不可读，无法查询");
404	      return false;
405	    }
406	
407	  if (n <= 0)
408	    {
409	      snprintf(reason, rcap, "还没有已确认点位");
410	      return false;
411	    }
412	
413	  rc = vg_vi_resolve_point(text, points, n, &res, token, sizeof(token));
414	
415	  if (rc == VG_AGENT_QUERY_AMBIG)
416	    {
417	      snprintf(reason, rcap, "有多个点位匹配，请报点位 ID");
418	      return false;
419	    }
420	
421	  if (rc == VG_AGENT_QUERY_NOT_FOUND && vg_vi_is_followup(text))
422	    {
423	      point_id = vg_vs_context_point(&g_vr.s);
424	      if (point_id == NULL || point_id[0] == '\0')
425	        {
426	          snprintf(reason, rcap, "请先报点位 ID 或完整名称");
427	          return false;
428	        }
429	    }
430	  else if (rc == VG_AGENT_QUERY_OK)
431	    {
432	      point_id = points[res.index].id;
433	      vg_vs_set_context_point(&g_vr.s, point_id, vr_now_ms());
434	    }
435	  else
436	    {
437	      snprintf(reason, rcap, "没有找到这个点位，请报点位 ID 或完整名称");
438	      return false;
439	    }
440	
441	  if (target_id && icap > 0)
442	    {
443	      snprintf(target_id, icap, "%s", point_id);
444	    }
445	
446	  if (intent.intent == VG_VI_RECOVERY)
447	    {
448	      snprintf(question, qcap,
449	               "查询点位 %s 的告警是否已经恢复，请调用 vg_alarm_recovery。",
450	               point_id);
451	      snprintf(tool, tcap, "vg_alarm_recovery");
452	      snprintf(tool_json, jcap, "{\"point_id\":\"%s\"}",
453	               point_id);
454	    }
455	  else
456	    {
457	      snprintf(question, qcap,
458	               "查询点位 %s 的当前读数，请调用 vg_point_read。",
459	               point_id);
460	      snprintf(tool, tcap, "vg_point_read");
461	      snprintf(tool_json, jcap, "{\"query\":\"%s\"}",
462	               point_id);
463	    }
464	
465	  return true;
466	}
