468	/* Both display and speech use the private snapshot captured for this read. */
469	static bool vr_render_answer(const struct vg_voice_facts *f, char *display,
470	                             size_t dcap, char *speech, size_t scap)
471	{
472	  if (f == NULL || f->seq == 0) return false;
473	  display[0] = '\0';
474	  speech[0] = '\0';
475	  if (f->has_recovery)
476	    vg_va_render_recovery(f, display, dcap, speech, scap);
477	  else if (f->has_point)
478	    vg_va_render_point(f, display, dcap, speech, scap);
479	  else
480	    vg_va_render_anomalies(f, display, dcap, speech, scap);
481	  return true;
482	}
