526	/* Execute the resolved read-only tool and render the answer from the
527	 * facts it publishes.  The tool runs through the agent tool registry, so
528	 * the same permission check, rate limit and audit path apply as in a
529	 * ReAct round, and the answer never comes from the model text. */
530	
531	static uint32_t vr_answer_from_tool(uint32_t gen, const char *tool,
532	                                    const char *tool_json,
533	                                    uint32_t config_version)
534	{
535	  char display[VG_VOICE_DISPLAY_MAX];
536	  char speech[VG_VS_TEXT_MAX];
537	  struct vg_voice_facts facts;
538	  char out[2048];
539	  bool captured;
540	  int rc;
541	
542	  if (!vg_voice_facts_capture_begin(&facts))
543	    {
544	      vr_ui_error("数据查询忙，请重试");
545	      return vg_vs_agent_result(&g_vr.s, gen, false, "facts busy",
546	                                vr_now_ms());
547	    }
548	
549	  out[0] = '\0';
550	  rc = tool_registry_execute(tool, tool_json, out, sizeof(out));
551	  captured = vg_voice_facts_capture_end();
552	  syslog(LOG_INFO, "[vgvoice] intent read %s rc=%d captured=%d seq=%u\n",
553	         tool, rc, captured, (unsigned)facts.seq);
554	  vr_log_stage("facts_end");
555	  if (g_vr.cancel) return 0;
556	
557	#ifdef CONFIG_VG_BUS_DISCOVER
558	  if (vg_live_points_gen() != config_version)
559	    {
560	      vr_ui_error("点表已变更，请重新提问");
561	      return vg_vs_agent_result(&g_vr.s, gen, false, "config changed",
562	                                vr_now_ms());
563	    }
564	#endif
565	
566	  facts.config_version = config_version;
567	  if (rc != 0 || !captured ||
568	      (int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0 ||
569	      !vr_render_answer(&facts, display, sizeof(display), speech,
570	                         sizeof(speech)))
571	    {
572	      vr_ui_error("没有拿到可核对的数据，请重试");
573	      return vg_vs_agent_result(&g_vr.s, gen, false, "no facts",
574	                                vr_now_ms());
575	    }
576	
577	  /* The session keeps only a short copy for its own bookkeeping; the full
578	   * list is published to the overlay separately. */
579	
580	  pthread_mutex_lock(&g_vr.ui_lock);
581	  snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", display);
582	  pthread_mutex_unlock(&g_vr.ui_lock);
583	
584	  return vg_vs_agent_result(&g_vr.s, gen, true, speech, vr_now_ms());
585	}
586	
587	static uint32_t vr_stage_agent(const char *text, uint32_t gen)
588	{
589	  char question[320];
590	  char reason[128];
591	  char tool[32];
592	  char tool_json[96];
593	  char target_id[48];
594	  char display[VG_VOICE_DISPLAY_MAX];
595	  char speech[VG_VS_TEXT_MAX];
596	  struct vg_voice_facts agent_facts;
597	  bool capturing = false;
598	  bool captured = false;
599	  uint32_t config_version = g_vr.s.config_version;
600	  tool[0] = '\0';
601	  tool_json[0] = '\0';
602	  target_id[0] = '\0';
603	  vr_log_stage("agent_begin");
604	
605	  if (!vr_build_question(text, question, sizeof(question), tool, sizeof(tool),
606	                         tool_json, sizeof(tool_json), target_id,
607	                         sizeof(target_id), reason, sizeof(reason)))
608	    {
609	      vr_ui_error(reason);
610	      return vg_vs_agent_result(&g_vr.s, gen, false, reason, vr_now_ms());
611	    }
612	
613	#ifdef CONFIG_VG_VOICE_DIRECT_TOOL
614	  /* The intent and the exact point are already resolved here, and the
615	   * answer is rendered from the published facts, so a model round would
616	   * only repeat that choice while spending 5 to 9 s of the 30 s budget
617	   * on the request.  The read-only tool runs directly instead. */
618	
619	  vr_ui_set_status("查询中");
620	  vr_ui_publish();
621	  vg_vs_agent_started(&g_vr.s, gen, vr_now_ms());
622	  vr_log_stage("tool_direct");
623	
624	  return vr_answer_from_tool(gen, tool, tool_json, config_version);
625	#else
626	
627	  for (;;)
628	    {
629	      int queued;
630	      if (g_vr.cancel)
631	        {
632	          if (capturing)
633	            {
634	              vg_voice_facts_capture_end();
635	            }
636	          return 0;
637	        }
638	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
639	        {
640	          if (capturing)
641	            {
642	              vg_voice_facts_capture_end();
643	            }
644	          vr_ui_error("等待查询超时");
645	          return vg_vs_agent_result(&g_vr.s, gen, false,
646	                                    "agent queue timeout", vr_now_ms());
647	        }
648	      queued = vg_agent_round_queue_voice(question, g_vr.s.deadline_ms);
649	      if (queued == 0)
650	        {
651	          vg_voice_facts_set_config_version(config_version);
652	          capturing = vg_voice_facts_capture_request(&agent_facts,
653	                          vg_agent_round_voice_serial(), config_version);
654	          break;
655	        }
656	      if (queued != -EBUSY)
657	        {
658	          if (capturing)
659	            {
660	              vg_voice_facts_capture_end();
661	            }
662	          vr_ui_error("查询暂不可用，请稍后再试");
663	          return vg_vs_agent_result(&g_vr.s, gen, false,
664	                                    "agent unavailable", vr_now_ms());
665	        }
666	
667	      /* Keep the one pending voice question within its original budget.
668	       * The background owner finishes and consumes its own result. */
669	      vr_ui_set_status("等待后台任务");
670	      vr_ui_publish();
671	      vg_agent_round_tick();
672	      usleep(VR_AGENT_POLL_MS * 1000u);
673	    }
674	
675	  vr_ui_set_status("查询中");
676	  vr_ui_publish();
677	  vr_log_stage("agent_queued");
678	
679	  vg_vs_agent_started(&g_vr.s, gen, vr_now_ms());
680	
681	  if (!vr_wait_agent(g_vr.s.deadline_ms))
682	    {
683	      if (capturing)
684	        {
685	          vg_voice_facts_capture_end();
686	        }
687	
688	      /* The round may still be running; its reply is discarded because the
689	       * generation no longer matches once this call returns an error. */
690	
691	      if (g_vr.cancel)
692	        {
693	          return 0;
694	        }
695	
696	      /* Give up the agent slot: otherwise the discarded round keeps the client
697	       * busy and the next question is refused for up to its 300 s timeout. */
698	
699	      vg_agent_round_abandon_owned(VG_AGENT_ROUND_OWNER_VOICE);
700	
701	      vr_ui_error((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0
702	                    ? "查询超时" : "查询失败，请重试");
703	      return vg_vs_agent_result(&g_vr.s, gen, false, "agent failed",
704	                                vr_now_ms());
705	    }
706	
707	  {
708	    vg_agent_round_clear();
709	    vr_log_stage("agent_reply");
710	    if (capturing)
711	      {
712	        captured = vg_voice_facts_capture_end();
713	      }
714	    if (g_vr.cancel) return 0;
715	    if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
716	      {
717	        vr_ui_error("查询超时");
718	        return vg_vs_agent_result(&g_vr.s, gen, false, "agent timeout",
719	                                  vr_now_ms());
720	      }
721	  }
722	
723	  /* If the agent tool invocation already published matching facts, reuse
724	   * them directly to save 400-800 ms of redundant tool execution. */
725	
726	  bool facts_match = false;
727	  if (captured && agent_facts.seq != 0)
728	    {
729	      if (strcmp(tool, "vg_anomaly_read") == 0)
730	        {
731	          facts_match = agent_facts.anomaly_seen > 0;
732	        }
733	      else if (strcmp(tool, "vg_alarm_recovery") == 0)
734	        {
735	          facts_match = agent_facts.has_recovery &&
736	                        agent_facts.recovery.kind == VG_RUNTIME_KIND_THRESHOLD &&
737	                        strcmp(agent_facts.recovery.id, target_id) == 0;
738	        }
739	      else if (strcmp(tool, "vg_point_read") == 0)
740	        {
741	          facts_match = agent_facts.has_point &&
742	                        strcmp(agent_facts.point_id, target_id) == 0;
743	        }
744	    }
745	
746	  if (facts_match)
747	    {
748	      syslog(LOG_INFO, "[vgvoice] reused agent facts for %s seq=%u\n",
749	             tool, (unsigned)agent_facts.seq);
750	      syslog(LOG_INFO, "[vgvoice] intent read %s rc=0 captured=1 seq=%u\n",
751	             tool, (unsigned)agent_facts.seq);
752	      vr_log_stage("facts_end");
753	
754	#ifdef CONFIG_VG_BUS_DISCOVER
755	      if (vg_live_points_gen() != config_version)
756	        {
757	          vr_ui_error("点表已变更，请重新提问");
758	          return vg_vs_agent_result(&g_vr.s, gen, false, "config changed",
759	                                    vr_now_ms());
760	        }
761	#endif
762	
763	      agent_facts.config_version = config_version;
764	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) > 0 &&
765	          vr_render_answer(&agent_facts, display, sizeof(display), speech,
766	                           sizeof(speech)))
767	        {
768	          pthread_mutex_lock(&g_vr.ui_lock);
769	          snprintf(g_vr.ui.answer, sizeof(g_vr.ui.answer), "%s", display);
770	          pthread_mutex_unlock(&g_vr.ui_lock);
771	
772	          return vg_vs_agent_result(&g_vr.s, gen, true, speech, vr_now_ms());
773	        }
774	    }
775	
776	  /* Fallback: read once more via the tool and capture only this thread's
777	   * publication if the model tool did not supply matching facts. */
778	
779	  return vr_answer_from_tool(gen, tool, tool_json, config_version);
780	#endif
781	}
782	
783	static uint32_t vr_stage_tts(uint32_t gen)
784	{
785	  struct vg_vc_info info;
786	  enum vg_vc_result rc;
787	  vela_req_ctl_t ctl;
788	
789	  ctl.deadline_ms = g_vr.s.deadline_ms;
790	  ctl.cancel = &g_vr.cancel;
791	
792	  /* 重试播报也要暂停已恢复的后台请求，且沿用本次播报预算。 */
793	  while (vg_agent_round_voice_reserve() != 0)
794	    {
795	      if (g_vr.cancel) return 0;
796	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
797	        return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
798	      usleep(20000);
799	    }
800	
801	  vr_ui_set_status("合成语音");
802	  vr_ui_publish();
803	  vr_log_stage("tts_begin");
804	
805	  __atomic_fetch_add(&g_vr.tts_requests, 1, __ATOMIC_RELAXED);
806	  rc = vg_voice_cloud_tts(g_vr.s.answer, VG_VC_TTS_WAV_PATH, &ctl, &info);
807	
808	  syslog(LOG_INFO, "[vgvoice] tts rc=%s status=%d pcm=%u resp=%u ms=%u\n",
809	         vg_vc_result_name(rc), info.status, (unsigned)info.audio_bytes,
810	         (unsigned)info.resp_bytes, (unsigned)info.elapsed_ms);
811	  vr_log_stage("tts_end");
812	
813	  if (g_vr.cancel)
814	    {
815	      unlink(VG_VC_TTS_WAV_PATH);
816	      return 0;
817	    }
818	
819	  if (rc != VG_VC_OK)
820	    {
821	      /* The text is still valid; only playback failed. */
822	
823	      return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
824	    }
825	
826	  if (g_vr.cancel)
827	    {
828	      unlink(VG_VC_TTS_WAV_PATH);
829	      return 0;
830	    }
831	
832	  if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0 ||
833	      vg_voice_play_file(VG_VC_TTS_WAV_PATH) != 0)
834	    {
835	      unlink(VG_VC_TTS_WAV_PATH);
836	      return vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
837	    }
838	
839	  syslog(LOG_INFO, "[vgvoice] first_playable gen=%u elapsed_ms=%u\n",
840	         (unsigned)gen, (unsigned)(vr_now_ms() - g_vr.s.submit_ms));
841	  vr_log_stage("play_posted");
842	  vr_ui_set_status("播报中");
843	  vr_ui_publish();
844	
845	  {
846	    uint32_t actions = vg_vs_tts_result(&g_vr.s, gen, true, vr_now_ms());
847	    uint32_t limit = 60000;
848	    struct stat st;
849	
850	    if (stat(VG_VC_TTS_WAV_PATH, &st) == 0 && st.st_size > 44)
851	      {
852	        /* 16 kHz stereo 16-bit: 64000 bytes per second. */
853	
854	        limit = (uint32_t)((st.st_size - 44) / 64) + VR_PLAY_EXTRA_MS;
855	      }
856	
857	    bool idle = false;
858	    uint32_t started = vr_now_ms();
859	    while (!g_vr.cancel && vr_now_ms() - started < limit)
860	      {
861	        if ((idle = vr_wait_voice_idle(100))) break;
862	      }
863	    bool completed = idle;
864	    if (!idle)
865	      {
866	        vg_voice_cancel();
867	        idle = vr_wait_voice_idle(2000);
868	      }
869	    if (idle) unlink(VG_VC_TTS_WAV_PATH);
870	    if (g_vr.cancel) return 0;
871	
872	    struct vg_voice_stats played;
873	    vg_voice_get_stats(&played);
874	    if (!completed || !idle || played.last_result != VG_VOICE_OK)
875	      actions |= vg_vs_tts_result(&g_vr.s, gen, false, vr_now_ms());
876	    else
877	      actions |= vg_vs_play_done(&g_vr.s, gen, vr_now_ms());
878	    return actions;
879	  }
880	}
881	
882	/* ── action loop ────────────────────────────────────────────────── */
883	
884	static void vr_run_actions(uint32_t actions)
885	{
886	  int guard;
887	
888	  for (guard = 0; guard < 8 && actions != 0; guard++)
889	    {
890	      uint32_t next = 0;
891	
892	      if ((actions & VG_VS_ACT_STOP_PLAYBACK) != 0)
893	        {
894	          (void)vg_voice_cancel();
895	          if (vr_wait_voice_idle(2000))
896	            {
897	              next |= vg_vs_audio_stopped(&g_vr.s, vr_now_ms());
898	            }
899	          else
900	            {
901	              vr_ui_error("播放未能停止");
902	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
903	            }
904	        }
905	
906	      if ((actions & VG_VS_ACT_CANCEL_AGENT) != 0)
907	        {
908	          /* A new press replaced the question.  Release the agent slot so
909	           * the replacement can be submitted; the old reply is dropped by
910	           * its serial. */
911	
912	          vg_agent_round_abandon_owned(VG_AGENT_ROUND_OWNER_VOICE);
913	        }
914	
915	      if ((actions & VG_VS_ACT_STOP_RECORD) != 0)
916	        {
917	          if (g_vr.record_generation != 0)
918	            {
919	              (void)vg_voice_finish_owned_silent(g_vr.record_generation);
920	              g_vr.record_generation = 0;
921	            }
922	          /* END_SILENT 会在采集槽里留下原始 PCM 等待上传取用；取消路径
923	           * 没有后续取用，必须显式清零释放，否则残留音频留在内存。 */
924	          if (g_vr.clip_generation != 0)
925	            {
926	              (void)vg_voice_finish_owned(g_vr.clip_generation, true);
927	              g_vr.clip_generation = 0;
928	            }
929	        }
930	
931	      if ((actions & VG_VS_ACT_START_RECORD) != 0)
932	        {
933	          uint32_t gen = 0;
934	          int rc;
935	
936	          /* A previous round may still be writing its WAV.  Starting a
937	           * recording on top of that produced a phantom capture and then
938	           * "录音未正常结束" at the next stage; wait for the worker to settle
939	           * first and fail with a clear reason if it does not. */
940	
941	          if (!vg_voice_wait_idle(2000))
942	            {
943	              vr_ui_error("录音设备忙，请稍后再试");
944	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
945	            }
946	          else if ((rc = vg_voice_record_begin_owned(&gen)) < 0)
947	            {
948	              vr_ui_error("录音启动失败");
949	              next |= vg_vs_end(&g_vr.s, vr_now_ms());
950	            }
951	          else
952	            {
953	              g_vr.cancel = g_vr.end_pending || g_vr.press_pending || g_vr.quit;
954	              g_vr.record_generation = gen;
955	              g_vr.clip_generation = gen;
956	              vr_ui_clear_error();
957	              vr_ui_set_status("录音中");
958	
959	              pthread_mutex_lock(&g_vr.ui_lock);
960	              g_vr.ui.answer[0] = '\0';
961	              g_vr.ui.error[0] = '\0';
962	              pthread_mutex_unlock(&g_vr.ui_lock);
963	            }
964	        }
965	
966	      if ((actions & VG_VS_ACT_START_ASR) != 0)
967	        {
968	          uint32_t gen = g_vr.s.generation;
969	          char text[VG_VS_TEXT_MAX];
970	
971	          text[0] = '\0';
972	
973	          if (g_vr.cancel) return;
974	
975	          /* The recorder stops the PDM stream, drains and writes the WAV;
976	           * 2 s was tight enough to lose a round right after playback. */
977	
978	          vr_log_stage("asr_wait_recorder");
979	          if (!vr_wait_voice_idle(5000))
980	            {
981	              vr_ui_error("录音未正常结束");
982	              next |= vg_vs_asr_result(&g_vr.s, gen, false, NULL,
983	                                       vr_now_ms());
984	            }
985	          else if (!vr_stage_asr(text, sizeof(text)))
986	            {
987	              if (!g_vr.cancel)
988	                {
989	                  next |= vg_vs_asr_result(&g_vr.s, gen, false, NULL,
990	                                           vr_now_ms());
991	                }
992	            }
993	          else
994	            {
995	              next |= vg_vs_asr_result(&g_vr.s, gen, true, text,
996	                                       vr_now_ms());
997	            }
998	        }
999	
1000	      if ((actions & VG_VS_ACT_QUEUE_AGENT) != 0)
1001	        {
1002	          if (g_vr.cancel) return;
1003	          next |= vr_stage_agent(g_vr.s.text, g_vr.s.generation);
1004	        }
1005	
1006	      if ((actions & VG_VS_ACT_START_TTS) != 0)
1007	        {
1008	          if (g_vr.cancel) return;
1009	          next |= vr_stage_tts(g_vr.s.generation);
1010	        }
1011	
1012	      if ((actions & VG_VS_ACT_SHOW_RESULT) != 0)
1013	        {
1014	          vr_show_result();
1015	        }
1016	
1017	      if ((actions & VG_VS_ACT_SHOW_ERROR) != 0)
1018	        {
1019	          vr_show_error();
1020	        }
1021	
1022	      if ((actions & VG_VS_ACT_HIDE_OVERLAY) != 0)
1023	        {
1024	          vg_agent_round_voice_release();
1025	          pthread_mutex_lock(&g_vr.ui_lock);
1026	          g_vr.ui.visible = false;
1027	          g_vr.ui.status[0] = '\0';
1028	          g_vr.ui.error[0] = '\0';
1029	          g_vr.ui.answer[0] = '\0';
