1060	      clock_gettime(CLOCK_REALTIME, &ts);
1061	      ts.tv_nsec += VR_TICK_MS * 1000000L;
1062	      if (ts.tv_nsec >= 1000000000L)
1063	        {
1064	          ts.tv_sec += 1;
1065	          ts.tv_nsec -= 1000000000L;
1066	        }
1067	
1068	      (void)sem_timedwait(&g_vr.wake, &ts);
1069	
1070	      now = vr_now_ms();
1071	
1072	      if (g_vr.press_pending)
1073	        {
1074	          g_vr.press_pending = false;
1075	          actions = vg_vs_press(&g_vr.s, now);
1076	          vr_run_actions(actions);
1077	          now = vr_now_ms();
1078	        }
1079	
1080	      if (g_vr.submit_pending)
1081	        {
1082	          g_vr.submit_pending = false;
1083	          actions = vg_vs_release(&g_vr.s, now);
1084	          vr_run_actions(actions);
1085	          now = vr_now_ms();
1086	        }
1087	
1088	      /* Overlay commands arrive from the LVGL thread.  They only set a flag
1089	       * here: the worker runs the pipeline, so a retry that needs 30 s of
1090	       * network never blocks the UI. */
1091	
1092	      if (g_vr.end_pending)
1093	        {
1094	          g_vr.end_pending = false;
1095	          vr_run_actions(vg_vs_end(&g_vr.s, now));
1096	          now = vr_now_ms();
1097	        }
1098	
1099	      if (g_vr.retry_pending)
1100	        {
1101	          g_vr.retry_pending = false;
1102	          g_vr.cancel = g_vr.end_pending || g_vr.press_pending || g_vr.quit;
1103	          vr_run_actions(vg_vs_retry_tts(&g_vr.s, now));
1104	          now = vr_now_ms();
1105	        }
1106	
1107	      /* The session belongs to this thread.  The overlay's hold and mute
1108	       * switches arrive as pending values so no other thread mutates it. */
1109	
1110	      if (g_vr.hold_pending)
1111	        {
1112	          g_vr.hold_pending = false;
1113	          g_vr.hold = g_vr.hold_value;
1114	          vg_vs_result_hold(&g_vr.s, g_vr.hold, now);
1115	        }
1116	
1117	      if (g_vr.mute_pending)
1118	        {
1119	          g_vr.mute_pending = false;
1120	          g_vr.muted = g_vr.mute_value;
1121	          vg_vs_set_muted(&g_vr.s, g_vr.mute_value);
1122	        }
1123	
1124	#ifdef CONFIG_VG_BUS_DISCOVER
1125	      /* A committed point-table change bumps the live generation.  Feed it to
1126	       * the session so an in-flight question ends instead of answering from a
1127	       * table that may no longer contain the points it names. */
1128	
1129	      vg_vs_set_config_version(&g_vr.s, vg_live_points_gen());
1130	#endif
1131	
1132	      actions = vg_vs_tick(&g_vr.s, now);
1133	      vr_run_actions(actions);
1134	      vr_log_cancel_settled();
1135	
1136	      if (g_vr.s.state == VG_VS_RESULT && !g_vr.hold)
1137	        {
1138	          /* Nothing to do: the session owns the 15 s timer. */
1139	        }
1140	    }
1141	
1142	  return NULL;
1143	}
