 *   - A phase that was not executed is AGENT_T_NA, never zero.
 *   - DNS and TCP are one fused phase here: mbedtls_net_connect() resolves
 *     and connects in one call.  fused_dns_tcp says so; splitting them
 *     would need a second resolver call and would change the measurement.
 *   - ttfb is the first byte of the HTTP response, which is the status
 *     line.  This path is not streamed, so it is not a model first token.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <time.h>

#ifdef __cplusplus
extern "C" {
#endif

/* A phase that did not run.  Zero is a real measurement (an instant copy),
 * so it must not double as "not applicable". */

#define AGENT_T_NA (-1)

typedef struct {
    /* Transport phases, filled by vela_tls. */

    int32_t pool_ms; /* pool slot acquisition and reuse check */
    int32_t dns_tcp_ms; /* resolver plus TCP connect, fused */
    int32_t tls_setup_ms; /* RNG seed and TLS config, before the socket */
    int32_t tls_ms; /* TLS handshake */
    int32_t send_ms; /* request headers and body written */
    int32_t ttfb_ms; /* send done to first response byte */
    int32_t body_ms; /* first byte to body complete, headers included */

    /* LLM layer phases. */

    int32_t build_ms; /* request JSON construction and serialization */
    int32_t parse_ms; /* response JSON parse and field extraction */
    int32_t http_total_ms; /* whole transport call */
    int32_t llm_total_ms; /* whole llm_chat_tools call */
    int32_t backoff_ms; /* sleep before this attempt, 0 for the first */

    int http_rc; /* raw transport return value */
    int http_status; /* parsed HTTP status, 0 when unknown */
    uint32_t req_bytes; /* serialized request size */
    uint32_t resp_bytes; /* HTTP body bytes received */
    uint16_t attempt; /* 1-based attempt within this LLM call */

    bool reused; /* request ran on a pooled connection */
    bool fused_dns_tcp; /* dns_tcp_ms is a combined phase */
    bool proxy; /* request went through the CONNECT proxy */
    bool parse_ok; /* JSON parse and field extraction succeeded */
} agent_llm_timing_t;

/**
 * Monotonic milliseconds.  Wraps after about 49 days, which no board run
 * reaches; elapsed math below stays correct across the wrap anyway.
 */

static inline uint32_t agent_mono_ms(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }

    return (uint32_t)((uint64_t)ts.tv_sec * 1000u
        + (uint64_t)ts.tv_nsec / 1000000u);
}

static inline int32_t agent_elapsed_ms(uint32_t t0, uint32_t t1)
{
    uint32_t d = t1 - t0;

    /* A single request never runs for 24 days; a larger difference can only
     * mean the caller mixed clock bases.  Report it as unmeasured. */

    return d > 0x7fffffffu ? AGENT_T_NA : (int32_t)d;
}

/* Elapsed since *t0, then move *t0 to now.  Used for back-to-back phases. */

static inline int32_t agent_lap_ms(uint32_t* t0)
{
    uint32_t now = agent_mono_ms();
    int32_t ms = agent_elapsed_ms(*t0, now);

    *t0 = now;
    return ms;
}

/** Reset every field to "not measured" before one attempt. */
void agent_timing_reset(agent_llm_timing_t* t);

/**
 * Mark the transport phases as not applicable.  The proxy path cannot see
 * inside its tunnel, so it calls this and only reports the total.
 */
void agent_timing_no_transport(agent_llm_timing_t* t);

/**
 * Format one attempt as a single syslog line body, without the "[trace:...]"
 * prefix or a trailing newline.
 *
 * The request body, headers, API key and tool output are never included;
 * only sizes and timings are.  Returns the number of characters written,
 * or -1 when the buffer is too small.  A truncated line would drop fields
 * and read as a complete record, so this fails instead of truncating.
 */
int agent_timing_format_http(char* buf, size_t cap, int iteration,
    const agent_llm_timing_t* t);

#ifdef __cplusplus
}
#endif

int llm_chat_tools(const char *system_prompt, cJSON *messages,
    const char *tools_json, llm_response_t *resp,
    agent_llm_timing_t *out_timing)
{
    return llm_chat_tools_controlled(system_prompt, messages, tools_json,
        resp, out_timing, NULL);
}

int llm_chat_tools_controlled(const char* system_prompt, cJSON* messages,
    const char* tools_json, llm_response_t* resp,
    agent_llm_timing_t* out_timing, const vela_req_ctl_t *ctl)
{
    /* Local timing always exists so the code paths stay identical whether or
     * not the caller asked for it.  out_timing is a one-time copy at the end:
     * there is no shared state and no allocation. */

    agent_llm_timing_t local;
    agent_llm_timing_t* timing = &local;
    uint32_t call_t0 = agent_mono_ms();
    uint32_t mark = call_t0;

    agent_timing_reset(timing);

    memset(resp, 0, sizeof(*resp));
    if (agent_http_stop(ctl, call_t0)) {
        int stopped = agent_http_cancelled(ctl) ? AGENT_HTTP_ERR_CANCELLED
                                               : AGENT_HTTP_ERR_TIMEOUT;
        timing->http_rc = stopped;
        if (out_timing != NULL) {
            *out_timing = local;
        }
        return stopped;
    }

    /* Snapshot config under lock */
    char model[64];
    char api_key[128];
    char llm_host[128];

    pthread_mutex_lock(&s_llm_lock);
    memcpy(model, s_model, sizeof(model));
    memcpy(api_key, s_api_key, sizeof(api_key));
    memcpy(llm_host, s_llm_host, sizeof(llm_host));
    pthread_mutex_unlock(&s_llm_lock);

    if (api_key[0] == '\0') {
        timing->llm_total_ms = agent_elapsed_ms(call_t0, agent_mono_ms());
        if (out_timing != NULL) {
            *out_timing = local;
        }
        return ERROR;
    }

    cJSON* body = cJSON_CreateObject();

    cJSON_AddStringToObject(body, "model",
        model_name_for_api(model, llm_host));

    if (is_openai_compat_host(llm_host)) {
        cJSON_AddNumberToObject(body, "max_completion_tokens",
            AGENT_LLM_MAX_TOKENS_OPENAI);
    } else {
        cJSON_AddNumberToObject(body, "max_tokens",
            AGENT_LLM_MAX_TOKENS);
    }

    if (vg_voice_scope_model_options(body, system_prompt, llm_host, model,
                                    ctl != NULL))
        syslog(LOG_INFO, "[%s] scoped voice model: thinking disabled, max_tokens=256\n", TAG);

    /* Clone messages and prepend system message */
    cJSON* msgs = cJSON_Duplicate(messages, 1);
    cJSON* sys_msg = cJSON_CreateObject();

    cJSON_AddStringToObject(sys_msg, "role", "system");
    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
    cJSON_InsertItemInArray(msgs, 0, sys_msg);
    llm_sanitize_messages_for_api(msgs);
    cJSON_AddItemToObject(body, "messages", msgs);

    /* Convert tools to OpenAI format */
    cJSON* tools_arr = build_openai_tools_array(tools_json);

    if (tools_arr) {
        cJSON_AddItemToObject(body, "tools", tools_arr);
    }

    char* post_data = cJSON_PrintUnformatted(body);

    cJSON_Delete(body);
    if (!post_data) {
        timing->build_ms = agent_lap_ms(&mark);
        timing->llm_total_ms = agent_elapsed_ms(call_t0, agent_mono_ms());
        if (out_timing != NULL) {
            *out_timing = local;
        }
        return ERROR;
    }

    /* Fix the moment the request body was ready.  Retries must report the
     * same build cost; taking it from mark again later would fold the
     * previous HTTP call into it.  mark has not moved since call_t0 on this
     * path, so it is advanced here rather than measured against itself. */

    mark = agent_mono_ms();

    uint32_t build_ms = agent_elapsed_ms(call_t0, mark);

    timing->build_ms = build_ms;
    timing->req_bytes = (uint32_t)strlen(post_data);

    syslog(LOG_INFO,
        "[%s] OpenAI API with tools (model: %s, %d bytes)\n",
        TAG, model, (int)strlen(post_data));

    resp_buf_t rb = { 0 };
    int status = 0;
    int err = ERROR;
    int retry;

    /* Only the last attempt's transport phases are kept; backoff_ms and
     * attempt say how many tries it took to get there.  Attempts are not
     * summed because the phases would no longer add up to one request. */

    for (retry = 0; retry <= (ctl == NULL ? AGENT_LLM_MAX_RETRIES : 0); retry++) {
        unsigned int delay = 0;

        if (retry > 0) {
            delay = AGENT_LLM_RETRY_BASE_SEC << (retry - 1);
            syslog(LOG_WARNING, "[%s] Rate limited (429), retry %d/%d after %us\n",
                TAG, retry, AGENT_LLM_MAX_RETRIES, delay);
            sleep(delay);
        }

        agent_timing_reset(timing);
        timing->build_ms = build_ms;
        timing->req_bytes = (uint32_t)strlen(post_data);
        timing->backoff_ms = (int32_t)(delay * 1000u);
        timing->attempt = (uint16_t)(retry + 1);

        rb.len = 0;
        status = 0;
        mark = agent_mono_ms();
        if (ctl != NULL) {
            if (resp_buf_init(&rb, 4096) != OK) {
                err = ERROR;
            } else {
                vela_resp_sink_t sink = { .write = llm_control_sink, .ctx = &rb };
                size_t received = 0;
                err = llm_http_call_stream(post_data, NULL, &sink,
                    NULL, 0, &received, &status, timing, ctl);
            }
        } else {
            err = llm_http_call(post_data, &rb, &status, timing);
        }
        timing->http_total_ms = agent_elapsed_ms(mark, agent_mono_ms());

