```c
/* ── Public: chat with tools ──────────────────────────────── */

/* Controlled-stream sink: appends to the response buffer and, until the
 * first SSE "data:" line is seen, watches for it byte by byte so the
 * timing records when the model produced its first visible output.  The
 * transport ttfb (the HTTP status line) is a different, earlier mark;
 * both are reported and neither is renamed to mean the other.  State is
 * fixed-size on the caller's stack: no allocation on this path. */

struct llm_sink_obs {
    resp_buf_t *rb;
    agent_llm_timing_t *t;
    uint32_t req_mark; /* request start, the fallback anchor */
    bool first_seen;
    bool line_start; /* next byte begins an SSE line */
    size_t head_len; /* "data:" prefix matched so far */
};

static int llm_control_sink(void *ctx, const char *data, size_t len)
{
    static const char prefix[] = "data:";
    struct llm_sink_obs *obs = ctx;
    size_t i;

    for (i = 0; i < len; i++) {
        char c = data[i];

        if (!obs->first_seen) {
            if (obs->head_len == 0) {
                if (obs->line_start && c == prefix[0]) {
                    obs->head_len = 1;
                }
            } else if (c == prefix[obs->head_len]) {
                obs->head_len++;
                if (obs->head_len == sizeof(prefix) - 1) {
                    uint32_t anchor = obs->t->send_done_mono;
                    obs->first_seen = true;
                    obs->t->first_data_ms = agent_elapsed_ms(
                        anchor != 0 ? anchor : obs->req_mark, agent_mono_ms());
                }
            } else {
                obs->head_len = 0;
            }
        }

        obs->line_start = (c == '\n');
    }

    return resp_buf_append(obs->rb, data, len) == OK ? 0 : -1;
}
```

