struct stat st;
if (stat(VG_VC_TTS_WAV_PATH, &amp;st) == 0 &amp;&amp; st.st_size &gt; 44)
  {
    /* 16 kHz stereo 16-bit: 64000 bytes per second. */
    limit = (uint32_t)((st.st_size - 44) / 64) + VR_PLAY_EXTRA_MS;
